import type { ManagedSkill } from "./skill-catalog";

export const generatedSkills = JSON.parse(
  '[{"name":"nano-flow","version":"0.0.1","contentHash":"96b5e15194eb943b516c3f6d5b7b9c7db324676880532bdf8336ef932a653d73","files":[{"path":"extensions/hooks.json","content":"{\\n  \\"schema_version\\": 1,\\n  \\"hooks\\": [\\n    {\\n      \\"match\\": [\\"questing\\", \\"to-issues\\"],\\n      \\"mode\\": \\"manual\\",\\n      \\"message\\": \\"当前 skill 执行结束后, 询问用户当前 skill 是否完成 + 是否进入下一个 skill, 用户同意后, 调用下一个 skill(无须用户确认).\\"\\n    },\\n    {\\n      \\"match\\": [\\"to-issues\\"],\\n      \\"mode\\": \\"auto\\",\\n      \\"message\\": \\"当前 skill 内部确认及其执行结束后, 无需用户确认, 自动调用下一个 skill\\"\\n    },\\n    {\\n      \\"match\\": [\\"questing\\"],\\n      \\"mode\\": \\"auto\\",\\n      \\"message\\": \\"当前 skill 明确要求的人工澄清及其产物确认照常执行；其余内部确认及执行结束后的推进无需用户确认，自动调用下一个 skill。\\"\\n    },\\n    {\\n      \\"match\\": [\\"code-delivery\\"],\\n      \\"message\\": \\"任何准入判断前先完整读取 `<nano-flow-skill-root-dir>/extensions/QUESTIONS.md` 和 `<nano-flow-skill-root-dir>/extensions/workflows/README.md`，以用户输入和当前上下文作为已有答案，选择并询问全部相关问题。问题集未清空时结论为 `not ready`。基线首次建立或实质漂移时，向用户提交简短基线卡并等待确认；仍适用的既有确认直接复用。交付遇到 block 时，优先从该 workflows 索引及对应业务域 workflow 寻找解决方法。\\"\\n    }\\n  ]\\n}\\n"},{"path":"extensions/QUESTIONS.md","content":""},{"path":"extensions/skills/code-spec/SKILL.md","content":"---\\nname: code-spec\\ndescription: 编写、修改或审查代码时，应用仓库的目录、命名、边界与语言规范。\\n---\\n\\n逐个核对触及的目录、文件、函数和外部边界；全部适用规则满足或命中「全局例外」时完成。\\n\\n## 目录与命名\\n\\n- `/src` 为 `level-1`，不存在时以项目根为 `level-1`；最多 4 层，`level-4` 只放文件。\\n- 每目录最多 13 个文件，超过时按领域归入文件夹。\\n- 文件和目录使用 `kebab-case`，按实际领域职责命名，如 `tab-group-state.ts`、`terminal-cleanup.ts`。\\n- 泛化名称（`helpers`、`utils`、`common`、`components`、`hooks` 等）仅在 `level-2` 允许（也包括 `libs`、`config`）。其他层只能想到泛名时，拆分过多职责或按操作对象命名。\\n\\n## 文件与边界\\n\\n- 文件最多 610 行、前端组件 377 行、函数 89 行；超过时按职责和复用边界重构。\\n- 默认命名导出/导入，确有需要时使用默认导出/导入。\\n- 注释使用中文，只解释原因、约束、取舍和风险，不复述代码的执行过程；非测试的增量与存量改动按需补充。\\n- 网络、SDK、文件系统等外部边界有错误处理；内部流转数据默认可信，无须 schema/validator。\\n- 外部数据默认不可信：客户端 HTTP 响应递归使用 TypeScript 可选链防空指针；用户输入与服务端 RPC/HTTP 请求使用项目 schema/validator。\\n- 测试与实现同级放置；E2E 可单独放在 tests 目录。\\n\\n## TS\\n\\n- 使用箭头函数，参数和返回值有类型注解。\\n- 用 `const = {} as const` 替代 `enum`，值联合类型从该对象派生。\\n- 确实无法收窄时通过 `type ISafeAny = any` 使用 `any`，其余情况使用明确类型。\\n\\n## CSS\\n\\n优先 Tailwind CSS；不存在时使用 SCSS/LESS/CSS Modules。\\n\\n## React\\n\\n- props 使用接口声明，最多 8 个属性，超过时重构组件。\\n- 使用箭头函数组件、`React.FC<Props>` 和命名导出；参数命名 `props` 并注明类型，在函数内解构。\\n- 按功能逻辑块组织组件，通用逻辑在顶部，最后返回 UI。\\n\\n## 全局例外\\n\\n工具链约定和自动生成的文件、目录除外；领域 skill 的规则优先。\\n"},{"path":"extensions/skills/code-test/mocking.md","content":"# 何时 Mock\\n\\n只在 system boundaries 使用 mock：外部 API、时间/随机性，以及必要时的数据库或文件系统；数据库优先 test DB。自有 classes/modules、内部协作者及其他受控对象不 mock，使用真实实现。自有远程服务和可本地替代依赖的 adapter 策略由 `/code-design` 指导。\\n\\n## Mockability\\n\\n外部依赖通过 injection 传入，避免在拥有业务逻辑的函数内创建客户端：\\n\\n```typescript\\nconst processPayment = (order, paymentClient) => paymentClient.charge(order.total);\\n```\\n\\n优先具体的 SDK-style 操作，避免让 mock 根据 generic fetcher 的 endpoint/options 分支：\\n\\n```typescript\\nconst api = {\\n  getUser: (id) => fetch(`/users/${id}`),\\n  getOrders: (userId) => fetch(`/users/${userId}/orders`),\\n  createOrder: (data) => fetch(\\"/orders\\", { method: \\"POST\\", body: data }),\\n};\\n```\\n\\n每个操作独立 mock，返回确定 shape；测试准备无须分派条件，所用 endpoint 和类型清晰。\\n"},{"path":"extensions/skills/code-test/SKILL.md","content":"---\\nname: code-test\\ndescription: 实现完成后，需要编写或评估 unit/integration tests、检查覆盖率时使用。\\n---\\n\\n# Code Test\\n\\n负责 `implementation → tests` 的测试阶段，以完成的生产代码和 spec 为输入，证明行为并识别错误实现。探索前按 领域定位规则（`<nano-flow-skill-root-dir>/references/DOMAIN.md`） 读取相关 `CONTEXT.md` 与 ADR，使测试命名和 interface vocabulary 对齐领域语言。\\n\\n## 流程\\n\\n1. 从 `/code-delivery` 基线取得质量门禁、public interfaces、critical paths 与 seams，承担测试类门禁。直接调用时，写测试前列出受测 seams 并与用户确认；interface 未定时使用 `/code-design` 确定边界。\\n2. 通过 public interfaces 测试 observable behavior，覆盖 spec 的成功、失败与关键边界。expected values 来自 spec、worked example 或 known-good literal 等独立事实源。\\n3. 先运行受影响的单个测试文件，按 public contract 判断失败来自测试还是实现；生产代码修正后从受影响测试重新开始。\\n4. 按仓库配置运行 coverage，记录命令、通过结果与报告。下方硬门禁全部成立时测试阶段完成；由调用者进入 `/verifying`，独立调用时继续执行该 skill。\\n\\n## 硬门禁\\n\\n- 受影响测试与完整 test suite 均通过。\\n- **覆盖率 ≥ 80%**：范围以仓库配置为准；未配置时至少包含本次修改的全部生产代码。报告有 statements、branches、functions、lines 时每项均达标；只有总指标时该项达标。仓库更严格门禁优先。\\n- 缺少 coverage tooling、报告或可复现命令时为 `blocked`；统计范围与行为断言保持完整，不能靠缩小范围或无断言测试抬高指标。\\n\\n## 测试原则\\n\\n`/code-design` 拥有 seam vocabulary；测试通过约定的 public interface 观察行为，替换依赖的 internal seam 保持在实现内。投入集中于预先商定的 seams、critical paths 与复杂逻辑，避免任意边界或内部结构。\\n\\n测试应读起来像 specification，并在行为不变的内部重构后继续通过。判断示例质量时读 [tests.md](tests.md)；外部 seam 需要 mock 时读 [mocking.md](mocking.md)。\\n\\n| Anti-pattern               | 识别信号                                                                      |\\n| -------------------------- | ----------------------------------------------------------------------------- |\\n| **Implementation-coupled** | mock 内部协作者、测 private methods 或 side channel；行为未变而重构使测试失败 |\\n| **Tautological**           | 用实现的同一算法计算 expected value，断言由构造保证通过                       |\\n| **Metric gaming**          | 仅执行代码、缩小范围或堆无行为断言；指标提高却无法识别相关错误实现            |\\n"},{"path":"extensions/skills/code-test/tests.md","content":"# 测试示例\\n\\n## Observable behavior\\n\\n**Integration-style** 测试通过真实 public interfaces 观察用户关心的行为，内部重构后仍成立；名称描述 WHAT，每个 test 一个 logical assertion。\\n\\n```typescript\\ntest(\\"用户可以使用有效 cart 结账\\", async () => {\\n  const cart = createCart();\\n  cart.add(product);\\n  const result = await checkout(cart, paymentMethod);\\n  expect(result.status).toBe(\\"confirmed\\");\\n});\\n```\\n\\n**Implementation-detail** 的信号：mock internal collaborators、测 private methods、断言内部调用次数/顺序、名称描述 HOW，或绕过 interface 检查内部状态；行为未变而重构使测试失败。\\n\\n通过可检索行为验证保存结果，避免直接查询数据库作为 side channel：\\n\\n```typescript\\ntest(\\"createUser 使 user 可被检索\\", async () => {\\n  const user = await createUser({ name: \\"Alice\\" });\\n  const retrieved = await getUser(user.id);\\n  expect(retrieved.name).toBe(\\"Alice\\");\\n});\\n```\\n\\n## Independent expected values\\n\\n**Tautological** 测试重算实现。例如用 `items.reduce((sum, i) => sum + i.price, 0)` 作为求和函数的 expected value，两者无法独立产生分歧。使用独立 known literal：\\n\\n```typescript\\ntest(\\"calculateTotal 对 line items 求和\\", () => {\\n  expect(calculateTotal([{ price: 10 }, { price: 5 }])).toBe(15);\\n});\\n```\\n"},{"path":"extensions/workflows/README.md","content":""},{"path":"FLOW.md","content":"# Flow 运行协议\\n\\n`/nano-flow` 驱动 `scripts/flow.mjs`；各 skill 拥有产物和完成标准。首次调用前从工作区根目录运行 `node <nano-flow-skill-root-dir>/scripts/flow.mjs --help`，以现场帮助查询参数。\\n\\n## 打开、执行、报告\\n\\n1. 新 Flow 用 `acquire --plan <path>` 创建并取得租约；已有 Flow 用 `status --plan <path>` 查看，再用 `acquire` 恢复。模式在创建时通过 `--mode manual|auto` 设置，默认 manual，创建后固定；新模式使用新 Flow 标识。\\n2. 仅在返回 `state=owned` 时，完整读取并执行 `next.skill`，原样传递 `next.message` 与 Flow context。\\n3. skill 完成标准成立后，用 `report --session <id> --step </skill> --result completed --evidence <ref>` 登记；只执行新返回的下一步。\\n\\n所有命令携带稳定的 `--plan`；Issue 操作另带 `--issue <NN>`。后续原样复用返回的 plan、issue、session。Plan 标识必须位于工作区内；采用 Issue 图时，它必须指向实际 Plan 目录。\\n\\n主流程由已登记证据推导：\\n\\n```text\\n/questing → /to-issues\\n               ├─ skipped   → /code-delivery → completed\\n               └─ completed → 逐个 Issue 的 /code-delivery → 全部 completed\\n```\\n\\n`/to-issues` 判断是否需要可恢复的 Issue 图，允许报告 `completed` 或 `skipped`，两者均须证据。其他 skill 只接受 `completed`。\\n\\n`/code-delivery` 内部完成准入、实现、测试、验证、审查和提交，提交成功后才报告 `completed`；证据引用本轮实际提交、交付物与验证结果。Flow 不登记中途准入，不执行 Git 提交，也不证明证据真实性。\\n\\n## 统一快照\\n\\n三个命令均返回 `{ plan, issue, session, mode, state, next, lease, issues, receipts }`。`next` 为 null 或 `{ skill, results, message? }`；`issues` 含 `{ id, status, lease, ready }`；receipts 始终为整个 Plan 的证据链，通过每项的 issue 区分 Plan 和 Issue 登记。\\n\\n| state     | 调用方动作                                 |\\n| --------- | ------------------------------------------ |\\n| available | acquire 取得租约后执行                     |\\n| owned     | 执行 next；长操作用 acquire 续租           |\\n| busy      | 等持有人释放或租约过期                     |\\n| blocked   | 解除障碍并提供证据后 acquire               |\\n| issues    | 按已确认优先级选择 ready Issue，再 acquire |\\n| completed | 本目标结束                                 |\\n\\n`status --session <id>` 仅用于识别该 session 已有的有效租约，既不领取也不续租；显示 next 不代表取得执行权。`state`、下一步和 Issue readiness 均为派生信息，不另存运行状态副本。\\n\\n## Issue 与租约\\n\\n`/to-issues=completed` 后，Plan 返回 Issue 集合；显式选择 Issue，脚本不自动挑选。领取要求直接依赖全部 completed。同一 session 在一个 Plan 内最多持有一个 Issue；不同 session 可并行领取互不阻塞的 Issue，每个目标只有一个有效租约。\\n\\n`acquire` 首次生成 session；同一持有人携带 session 再次调用即续租，租约过期后可接管。默认租期 30 分钟，可用 `--lease-seconds` 调整。租约过期只影响执行权，保留已登记证据与文档执行状态。\\n\\n暂停用 `report --session <id> --result paused` 释放租约，恢复仍用 acquire。真实阻塞仅用于 Issue：`report --session <id> --result blocked --reason <text> --release-condition <condition>` 写入障碍与解除条件并释放租约。暂停与阻塞无需 step 或 evidence。\\n\\n恢复 blocked Issue 须用 `acquire --evidence <ref>` 提供解除证据；不会因再次领取自动视为障碍已解决。交付完成前，Issue 的「交付记录」须包含交付物与验证证据。\\n\\nIssue frontmatter 的 status 是执行状态事实源：\\n\\n```text\\npending → in_progress → completed\\n              ↕\\n           blocked\\n```\\n\\n所有涉及 Issue 的写操作自动刷新 spec 派生状态与 Issue 表。全部 Issue completed 后，Plan 返回 completed；已有完成目标不会被重新初始化。后续修正创建新 Issue，新一轮 Flow 使用新 Plan 标识。\\n\\n完成后按 [DOMAIN.md](references/DOMAIN.md) 判断参考价值，将 Plan 移入 reference/ 或 archived/ 并重新运行领域校验；文档生命周期与执行状态正交。\\n\\n## Hooks\\n\\n[extensions/hooks.json](extensions/hooks.json) 拥有确认与推进提示：`match` 为 all 或主流程 skill 名称数组，mode 为 all、manual 或 auto，message 为非空单行文字。脚本将匹配当前 skill 和模式的消息按配置顺序拼入 next.message。\\n\\n携带 Flow context 的 skill 及其内部调用按该消息执行确认；复用已有有效授权，产物与证据仍须达到各 skill 的完成标准。\\n\\n## 存储与失败恢复\\n\\nschema 7 使用固定 `.flow/state.json`，保存 `plans[plan] = { mode, receipts, leases }`。Plan 短证据链和 Issue 文档共同决定当前位置；没有 phase、cursor 或 Issue status 副本。跨日继续读取同一文件；旧日文件保留但不读取，不迁移旧 schema。\\n\\n写入前验证参数、租约、顺序、依赖、证据与文档更新。多文件写入通过 pending journal 恢复：中断后，下一次 acquire 先恢复未完成写入。status 遇到 pending 时明确提示先 acquire，不返回可执行快照。\\n\\n恢复在预检和逐文件写入前比对内容，发现外部修改时保留现场并报冲突，核对并解决冲突后重试。外部编辑器不参与 Flow 写锁，检查与替换也不是原子操作；恢复期间暂停编辑同批文件。文档中的完成状态不会补造 receipt。完成登记必须同时保留本次证据与文档状态，校验失败不能留下部分更新。\\n"},{"path":"references/DOMAIN.md","content":"# 领域文档\\n\\n本文件是工作区领域文档布局、定位、命名和 Plan 生命周期的单一事实源。\\n\\n## 探索前先定位领域\\n\\n1. 阅读工作区根目录 `CONTEXT-MAP.md`，确定即将处理的业务域及其关系。\\n2. 阅读对应业务域的 `docs/{domain-name}/CONTEXT.md`。\\n3. 阅读该业务域中与当前工作相关的 `adr/`。\\n\\n跨业务域工作覆盖所有相关业务域，并读取 `CONTEXT-MAP.md` 中的关系。任一文件不存在时静默继续；术语或决策得到确认后，由 `/questing`按需创建或维护。\\n\\n## 布局\\n\\n领域内容只创建在工作区根目录的 multi-context 布局中：\\n\\n```text\\n/\\n├── CONTEXT-MAP.md\\n└── docs/\\n    ├── common/\\n    │   └── CONTEXT.md\\n    └── {domain-name}/\\n        ├── CONTEXT.md\\n        ├── adr/\\n        │   └── 0001-中文决策名.md\\n        └── plans/\\n            ├── active/\\n            │   └── YYYY-MM-DD-中文工作名/\\n            │       ├── story.md\\n            │       ├── spec.md\\n            │       └── 01-中文标题.md\\n            ├── reference/\\n            └── archived/\\n```\\n\\n- `CONTEXT-MAP.md` 只索引业务域及其关系；跨域关系只定义一次。\\n- `docs/common/` 承载多个业务域共同贡献的领域术语和 ADR。\\n- `docs/{domain-name}/CONTEXT.md` 只承载该业务域的 glossary，不承载 spec 或实现细节。\\n- `docs/{domain-name}/adr/` 承载该业务域拥有的 ADR；跨域决策只选择一个 owner，其他域使用链接引用。\\n- `docs/{domain-name}/plans/` 承载 `/questing`和 `/to-issues` 维护的 Plan。\\n- `domain-name` 使用稳定、简短的 kebab-case；新增业务域时同步创建 `CONTEXT.md` 并加入 `CONTEXT-MAP.md`。\\n\\n## 文档约束\\n\\n- `docs/` 下的 ADR、Plan 文件名与正文使用中文；约定名 `CONTEXT.md`、`spec.md`、`story.md`、稳定 ID、代码标识符和 `domain-name` 除外。\\n- `CONTEXT.md` 行数、`adr/*.md` 数量与单个 ADR 行数的上限由 `check-domain` 脚本强制，以其输出为准。\\n- ADR 使用域内连续编号 `0001-中文决策名.md`、`0002-中文决策名.md`。\\n- 超过任一上限时，按领域边界合并、拆分或移除沉积内容，使文档重新满足上限。\\n\\n## Plan 生命周期\\n\\nPlan 目录位置表达活性和参考价值：\\n\\n```text\\n新建 ──> active ──完成且仍有参考价值──> reference ──失去参考价值──> archived\\n                  └─废弃、过时或不再有用──────────────────────> archived\\n```\\n\\n- `active/`：当前正在推进；新 Plan 一律创建于此。\\n- `reference/`：全部 issue 已完成，且内容仍有参考价值。\\n- `archived/`：已废弃、已过时或不再有用；内容冻结，不再更新，也不再作为权威来源。\\n\\nPlan 生命周期与 Plan 内的执行状态正交：目录位置表达活性与价值，`spec.md` 和 issue frontmatter 的 `status:` 表达执行进度。移动 Plan 目录不修改 `status:`；未完成但被废弃的 Plan 可以保留原状态进入 `archived/`。\\n\\n## 领域语言与决策\\n\\n- 命名 Issue、测试、假设和重构提案时，使用对应 `CONTEXT.md` 中的 canonical term，不使用 glossary 明确排除的同义词。\\n- 所需概念尚未收录时，先判断它是否只是项目未使用的语言；确认存在领域缺口后，由 `/questing`维护 glossary。\\n- 输出与现有 ADR 冲突时显式指出冲突及重新讨论的理由，不静默覆盖。\\n"},{"path":"references/skills/code-delivery/SKILL.md","content":"---\\nname: code-delivery\\ndescription: spec、issue 或设计结论已明确，需要建立执行基线并交付代码时使用。\\n---\\n\\n# Code Delivery\\n\\n以唯一、可核查的 spec、issue 或已确认设计为权威输入。前置未决时保持 `not ready`；基线实质漂移时更新输入并重新准入。\\n\\n1. **准入**：核对输入已澄清、相关领域结论已落盘，从输入、工作区配置和用户约束建立或复用基线：\\n   - **工作环境**：实现、运行与验证所需的环境、服务和入口。\\n   - **执行契约**：范围、固定比较点、步骤、停止点、交付物和状态变更授权。\\n   - **质量门禁**：`/code-test` 与 `/verifying` 的最小集合，每项有事实来源、执行入口和通过条件。\\n\\n   基线完整、无矛盾且未决项清空时为 `ready`，开始实现。\\n\\n2. **实现**：遵循 `/code-spec`，完成全部交付物。\\n3. **测试**：执行 `/code-test`，补齐所需测试并通过测试类门禁。\\n4. **验收**：执行 `/verifying`，取得当前 diff 的 `passed` 结论。\\n5. **审查**：执行 `/code-review`，处理双轴发现至无阻塞项；修复后重跑受影响的测试、验收与审查。\\n6. **提交**：按执行契约与已有授权提交通过门禁的变更，报告 commit；缺少授权时先请求。\\n"},{"path":"references/skills/code-design/DEEPENING.md","content":"# Deepening\\n\\n按依赖类别 deepen shallow modules；术语见 [SKILL.md](SKILL.md)。\\n\\n## Dependency categories\\n\\n| 类别                    | 合并与依赖策略                                                                                                     | 测试                   |\\n| ----------------------- | ------------------------------------------------------------------------------------------------------------------ | ---------------------- |\\n| **In-process**          | 纯计算、内存状态、无 I/O；可直接合并，无须 adapter                                                                 | 通过新 interface 测试  |\\n| **Local-substitutable** | 有本地 stand-in（如 Postgres/PGLite、内存文件系统）即可 deepen；seam 保持 internal，external interface 不暴露 port | 用 stand-in 运行 suite |\\n| **Remote but owned**    | 自有远程服务使用 Ports & Adapters：module 拥有逻辑，port 定义契约，注入 HTTP/gRPC/queue transport adapter          | in-memory adapter      |\\n| **True external**       | 不受控制的第三方服务通过注入 port 接入                                                                             | mock adapter           |\\n\\n## Seam discipline\\n\\n- **Two adapters make a real seam**：至少两个合理 adapter（通常为生产与测试）才构成真实 port；single-adapter 形态保持 inline。\\n- 仅测试需要的 variation 留作 implementation 私有的 internal seam；调用方需要替换的 variation 才进入 external interface。\\n\\n## Replace, don\'t layer\\n\\n在 deepened module 的 interface 上迁移测试，通过可观察结果验证行为。原有行为覆盖迁移后，删除 shallow modules 上被替代的旧 unit tests，避免层层叠加。\\n\\n内部重构而行为不变时测试应继续通过；需随 implementation 改动的断言，检查是否越过 interface 或依赖内部状态。\\n"},{"path":"references/skills/code-design/DESIGN-IT-TWICE.md","content":"# Design It Twice\\n\\n为选定 deepening 候选项探索备选 interfaces 时使用。第一个想法未必最优；术语见 [SKILL.md](SKILL.md)。\\n\\n## 1. 界定 problem space\\n\\n向用户展示候选项的 [constraints、依赖类别](DEEPENING.md) 和说明性代码草图，然后立即进入设计。\\n\\nbrief 包含现有 coupling、不可改变的 domain invariants 与全部 constraints，草图未预设某个候选 interface 时完成。\\n\\n## 2. 派遣 sub-agents\\n\\n并行派遣至少 3 个 sub-agents，各自输出截然不同的 interface。为每个 agent 提供独立 technical brief：文件路径、coupling、依赖类别、seam 后的内容，以及本 skill 和相关 `CONTEXT.md` vocabulary。它独立于面向用户的 problem-space 说明。\\n\\n| Agent       | Design constraint                                                |\\n| ----------- | ---------------------------------------------------------------- |\\n| 1           | 最小化 interface，以 1–3 个入口为目标，最大化每个入口的 leverage |\\n| 2           | 最大化灵活性，支持多种 use cases 与扩展                          |\\n| 3           | 优化最常见调用方，使默认情况简单                                 |\\n| 4（适用时） | 围绕 Ports & Adapters 设计 cross-seam dependencies               |\\n\\n每个方案输出 interface（types、methods、params、invariants、顺序、错误）、调用用例、隐藏的 implementation、依赖与 adapters，以及 leverage 的收益和代价。\\n\\n至少三个方案在 interface shape 或 seam placement 上实质不同，均覆盖完整 brief 且可独立评估时完成。\\n\\n## 3. 展示并比较\\n\\n依次展示方案，再按同一组 constraints 比较 depth、locality、seam placement 与依赖策略。明确推荐及理由；可组合时提出 hybrid。\\n\\n所有方案可沿共同约束比较，推荐的收益与代价清楚，最终选择或待定决策已有记录时完成。\\n"},{"path":"references/skills/code-design/SKILL.md","content":"---\\nname: code-design\\ndescription: 设计 deep modules、收窄 interface、集中复杂性，或选择依赖策略、adapter 与模块边界方案时使用。\\n---\\n\\n# Code Design\\n\\n**Deep module** 让调用方学习较小的 interface 获得较多行为，让维护者把变化、知识与验证集中在一处。\\n\\n## Vocabulary\\n\\n命名、图示与方案比较统一使用：\\n\\n| 术语               | 定义                                                                                                         |\\n| ------------------ | ------------------------------------------------------------------------------------------------------------ |\\n| **Module**         | 拥有 interface 与 implementation 的函数、类、包或 vertical slice；避免以 component、service、unit 作同义词   |\\n| **Interface**      | 正确使用 module 必须知道的类型、invariants、顺序、错误、配置与重要性能约束，超出 signature 或 TS `interface` |\\n| **Implementation** | interface 后隐藏的行为与数据                                                                                 |\\n| **Depth**          | 每学习一个单位 interface 可获得多少行为；interface 接近 implementation 复杂度时为 shallow                    |\\n| **Seam**           | 无须修改调用点即可替换行为的位置，由 interface 定义；避免用 boundary 作同义词而与 bounded context 混淆       |\\n| **Adapter**        | 在 seam 上满足 interface 的具体实现                                                                          |\\n| **Leverage**       | 调用方从 depth 获得的复用收益                                                                                |\\n| **Locality**       | 同一变化、bug 与验证集中一处的维护收益                                                                       |\\n\\n## Design lens\\n\\n- **Depth 属于 interface**：以调用方理解成本下降衡量，implementation 行数增加不代表 depth。\\n- **Deletion test**：移除后复杂性在多个调用方重现，说明提供 locality；仅少一层转发则是 shallow middle man。\\n- **Interface is the test surface**：调用方与测试通过约定 interface 观察行为；验证需越过它时，重审 interface 或 seam placement。\\n- **Hide policy, expose intent**：module 隐藏顺序、重试、状态转换和依赖编排，调用方表达结果。\\n\\n逐个列出候选 module 的 interface、隐藏复杂性、adapters、可观察结果及变化集中处。无法指出 leverage 或 locality 时保持 inline 或继续重构。\\n\\n## Testability\\n\\ndependencies 从 policy owner 外部注入，内部协作方式由 module 拥有。优先暴露可观察结果；新 methods 与 parameters 只表达真实 use cases 和 invariants。\\n\\n每个新增或改变的 seam 都有真实 variation、测试通过约定 interface 观察行为、实现细节未泄漏给调用方时，设计检查完成。\\n\\n## Conditional references\\n\\n- shallow modules 因 dependencies 无法直接合并时，读 [DEEPENING.md](DEEPENING.md)，选择依赖类别、seam、adapter 和替换式测试策略。\\n- 关键 interface 有多个合理形态且显著影响 depth 或 locality 时，读 [DESIGN-IT-TWICE.md](DESIGN-IT-TWICE.md)，并行生成备选后比较。\\n"},{"path":"references/skills/code-review/SKILL.md","content":"---\\nname: code-review\\ndescription: 审查 PR、branch、commit range 或 WIP diff 时使用；分别检查 Standards 与 Spec。\\n---\\n\\n# Code Review\\n\\n**Standards** 与 **Spec** 独立：符合规范不保证需求正确，实现需求也不保证符合仓库规则。用并行 sub-agents 隔离 context，保留双轴报告。\\n\\n## 1. 固定范围\\n\\n解析用户指定的 commit、branch、tag 或 merge-base；未指定时从执行契约或 PR/branch 推断，仍有多个合理基准才询问。\\n\\n- 已提交 branch：`git diff <fixed-point>...HEAD`。\\n- staged/unstaged WIP：`git diff <fixed-point>`，包含基准后的提交与工作区变更。\\n\\n记录 diff 命令及 `git log <fixed-point>..HEAD --oneline`。fixed point 可解析、diff 非空、工作区是否纳入明确时完成。\\n\\n## 2. 定位来源\\n\\n- **Spec**：依次采用用户指定路径、匹配 branch/feature 的 `docs/{domain-name}/plans/`、用户确认的其他来源。用户确认不存在时记为 `not available`。\\n- **Standards**：适用的 `AGENTS.md`、`CONTRIBUTING.md`、编码规范与 `/code-spec`；完整读取 [SMELL-BASELINE.md](SMELL-BASELINE.md) 的判断型 heuristics。\\n\\n每个变更文件映射到适用 standards，每项可用 spec 要求有引用位置时完成。\\n\\n## 3. 并行审查\\n\\n给两个 agent 相同的 diff 命令、commit 列表与范围：\\n\\n| Agent         | 来源与输出                                                                                                                                  |\\n| ------------- | ------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **Standards** | 读取全部 standards 与 smell baseline；按文件、hunk 报告规则违反，另标 baseline smell，区分硬规则与 judgement；引用代码与规则，不超过 377 字 |\\n| **Spec**      | 读取全部 spec；报告缺失/部分实现、scope creep、行为存在但实现不符的要求；引用代码与 spec，不超过 377 字。Spec 不可用时不派遣                |\\n\\n每个已派遣 agent 均覆盖完整 diff，每项发现包含可复核位置、规则或 requirement、影响和理由时完成。\\n\\n## 4. 汇总\\n\\n在 `## Standards` 与 `## Spec` 分别呈现发现，保留各 agent 的严重度和顺序，各报发现数及最高严重度；不跨轴总排名。\\n\\n双轴均有明确结论、findings 可追溯时完成；已审查且无发现的轴报告 pass，Spec 不可用时明确说明。\\n"},{"path":"references/skills/code-review/SMELL-BASELINE.md","content":"# Standards smell baseline\\n\\n这些 Fowler code smells 是 judgement heuristics，不是硬性违规。仓库明确认可的形态覆盖本 baseline；工具已机械强制的内容不进入人工 review。\\n\\n- **Mysterious Name**：名称没有揭示实际职责。重命名；无法诚实命名通常表示设计仍含混。\\n- **Duplicated Code**：相同逻辑形态出现在多个变更位置。提取共同变化的形态。\\n- **Feature Envy**：method 使用另一个 object 的数据多于自身数据。把行为移向它依赖的数据。\\n- **Data Clumps**：同一组 fields 或 params 总是共同出现。用一个有领域含义的 type 表达它们。\\n- **Primitive Obsession**：primitive 或 string 承担了重要领域概念。提供能守住其不变量的 type。\\n- **Repeated Switches**：针对同一类型的条件 cascade 反复出现。集中 dispatch 或使用 polymorphism。\\n- **Shotgun Surgery**：一项逻辑变化迫使多个位置分散编辑。把共同变化收拢到一个 module。\\n- **Divergent Change**：一个 module 因多个不相关原因变化。按变化原因拆分职责。\\n- **Speculative Generality**：diff 为 spec 未要求的未来需求增加 abstraction 或 hook。收缩到当前真实需求。\\n- **Message Chains**：调用方暴露长 navigation chain。让最靠近数据的 module 隐藏 traversal。\\n- **Middle Man**：module 主要只是继续 delegate。把 interface 交给真正拥有行为的 module。\\n- **Refused Bequest**：subclass 或 implementer 忽略大部分继承契约。改用更诚实的 composition 或 interface。\\n\\n每个 smell finding 必须引用具体 hunk，说明为何该 heuristic 在此处成立，并给出与仓库规则一致的改进方向。\\n"},{"path":"references/skills/learning/agents/openai.yaml","content":"policy:\\n  allow_implicit_invocation: false\\n"},{"path":"references/skills/learning/ANKI.md","content":"# Anki 制卡\\n\\n将 Markdown 笔记、词表、现成问答或完形填空转换为卡片。\\n\\n## 1. 对齐批次\\n\\n从材料和环境推断配置，只询问阻塞预览的缺项：\\n\\n- 来源路径/内容与卡片类型。\\n- 根牌组、子牌组映射、笔记类型、字段、正反面、来源链接、标签和需保留的 HTML。\\n- 判重委托 `nnf anki` / AnkiConnect，默认整个集合判重，重复项跳过并记录；仅明确要求时创建重复项。\\n\\n每张候选配置明确，未验证信息标为假设时完成。\\n\\n## 2. 解析材料\\n\\n按章节与语义知识点划分，保留层级、来源行号；基础卡聚焦一个回忆目标，答案来自材料，补充内容单独标明。相同输入与规则产生相同牌组、字段和卡片边界。\\n\\nMarkdown 笔记默认每文件一张卡，记录 frontmatter `id`，子牌组取文件名去数字前缀与 `.md`：\\n\\n| 配置           | 默认值                                                    |\\n| -------------- | --------------------------------------------------------- |\\n| 根牌组         | `<topic>`；未指定时作为预览假设                           |\\n| 笔记类型、字段 | `基础`；`正面` / `背面`                                   |\\n| 正面           | `根牌组-章节名-知识点`                                    |\\n| 背面           | `<a href=\\"https://wiki.kongxiaohan.cn/<id>\\">跳转wiki</a>` |\\n\\n链接基址与 id 齐全才生成链接，否则背面格式待确认。每张候选有稳定源标识或 Markdown 范围，每个源条目恰好归入候选或排除之一时完成。\\n\\n## 3. 预览确认\\n\\n版本递增（v1、v2…），标明源条目与候选总数。每候选一行，展示唯一序号、来源、完整牌组路径及全部实际字段（HTML 原样）；公共类型、映射、标签与判重策略集中列出，差异入行。列明排除及原因、假设、未验证项和冲突。\\n\\n行数等于候选数、覆盖全部源条目、足以复现批次，且当前版本获用户明确确认后进入创建。用户修改、来源/映射改变或实际模板、字段、目标状态与预览不符时，重新预览并确认。\\n\\n## 4. 创建\\n\\n先读 `/nano-flow-cli` 的 Anki 路由，命令与 option 以 `nnf anki --help` 为准。仅通过 `nnf anki` 经 AnkiConnect 写本机 Anki，不直接读写数据库/collection。\\n\\n创建缺失牌组，按确认序号与判重策略逐条或批量写入；工具明确的重复记跳过，其他错误记失败并保留原因。\\n\\n**完成条件**：创建数 + 跳过数 + 失败数 = 已确认候选数，每个结果对应唯一预览序号。\\n\\n## 5. 回读核验\\n\\n从 Anki 回读笔记，逐项比对牌组、类型和关键字段。报告确认版本、候选总数、各牌组创建数、类型与映射、创建/跳过/失败数及原因、核验方法和未解决问题。\\n\\n回读与预览已逐项核对、计数和原因符合实际、不一致项均已明列时完成。\\n"},{"path":"references/skills/learning/SKILL.md","content":"---\\nname: learning\\ndescription: 整理高密度、可检索的 Markdown 笔记，或将笔记、词表、问答、完形填空材料转为 Anki 卡片。\\ndisable-model-invocation: true\\n---\\n\\n# Learning\\n\\n笔记执行第 1–4 步，按需继续 Anki；仅制卡时从已有材料进入第 5 步。\\n\\n## 1. 覆盖账本\\n\\n完整读取材料，逐个登记有意义的知识点，合并语义重复并保留全部来源位置。所有源内容已登记、知识点有来源且去重时完成。\\n\\n## 2. 组织笔记\\n\\n按概念体系与知识边界分组，每篇承载一个可独立学习的概念：\\n\\n- 篇幅随知识密度，限 144 行；超过时按语义拆分，无法再拆的连贯主题可超出并说明理由。\\n- 对齐已有笔记结构，目录最多二级，末级最多 13 个 Markdown 文件。\\n\\n账本中每个知识点有唯一目标文件与标题，且上述约束满足时完成。\\n\\n## 3. 写入笔记\\n\\n新建时使用 [TEMPLATE.md](TEMPLATE.md)，以唯一 UUID 替换 `<uuid>`；修改时保留 UUID。\\n\\n**费曼技巧优先于电报体**：先向初学者讲清，再压缩。准确术语首次通俗解释，发现理解盲点则反思修订。\\n\\n- 顶部问题覆盖全部知识点，回答后可完整讲解和主动复习；标题独立展现知识结构。\\n- H1 仅作主题，正文从 H2 按知识关系连续递进。\\n- 普通文本每 bullet 一个知识点，使用 `term: explanation;`；富文本优先代码块、表格、公式或图示。\\n- 优先解释概念与权衡，精确记忆处补充说明。\\n\\n账本中全部目标文件成功写入时完成。\\n\\n## 4. 验证笔记\\n\\n逐项核对源内容均有映射、知识点无重复主归属、新 UUID 已替换且工作区内唯一、旧 UUID 未变、标题可独立展现知识结构。\\n\\n全部核对及工作区已有的适用 Markdown 检查/文档构建通过时，笔记完成。\\n\\n## 5. Anki（可选）\\n\\n需要制卡时读 [ANKI.md](ANKI.md)，以本轮笔记或指定材料执行其流程与完成标准；否则在笔记验证后结束。\\n"},{"path":"references/skills/learning/TEMPLATE.md","content":"---\\nid: <uuid>\\n---\\n\\n# 文档主题\\n\\n问题 1; 问题 2; ...\\n\\n## 概念\\n\\n- term: 最短完整解释;\\n\\n## 代码示例\\n\\n- term: 最短完整解释;\\n\\n```text\\n最小示例\\n```\\n"},{"path":"references/skills/questing/DESIGN-TREE.md","content":"# Design tree\\n\\n**Design tree** 按决策依赖展开，答案决定下游问题。**Frontier** 是前置已有答案、当前可回答的全部问题。\\n\\n按 **rounds** 推进：\\n\\n1. **取证**：事实从代码与工具查明并保留来源；需进一步探索时委派 subagent，将其作为未决前置，仅暂停下游，其余 frontier 继续。事实查明后才回答依赖决策；blocker 记录现场与恢复条件。\\n2. **提问**：每轮覆盖整个 frontier，问题按本 quest 唯一递增编号，附推荐与理由；依赖本轮未决答案的问题留到下一轮。\\n3. **推进**：记录选择、排除分支、新节点和判断假设，再重算 frontier；上游改变使前置失效时，下游问答一并失效。\\n4. **收敛**：所有可达分支已访问、frontier 为空且无静默假设。\\n"},{"path":"references/skills/questing/DESIGN.md","content":"# 设计拷问\\n\\n按 Design [tree](DESIGN-TREE.md) 由 agent 自动回答，形成草案后交用户统一评价。涉及领域模型或 ADR 变更时先读 [DOMAIN.md](DOMAIN.md)，以现有 glossary 与 ADR 为约束；其他讨论的权威文档由调用者维护。\\n\\n## 1. 自动回答\\n\\n每轮列出全部问题的互斥选择、前置问题、下游边界、推荐及理由；agent 各选一项并说明理由，与推荐不同时解释分歧。\\n\\n首次写入前读 [审阅模板](#审阅模板)，在工作区根创建或续写 `.flow/quest/YYYY-MM-DD-中文工作名.md`。使用首次创建的本地日期，同一 quest 续写同一文件；遇到其他 quest 同名时细化工作名。本轮问答追加在「补充说明」前，替换占位符，保留推荐与选择的可比较性。\\n\\n每题有唯一选择及理由、全部问答已记录时本轮完成。重复至拷问收敛，此时仍为草案。\\n\\n## 2. 统一评价\\n\\n提供审阅文件，请用户评价全部问题并在「补充说明」补充遗漏。等待用户说明评价完成，再读回所有轮次，按依赖顺序重放：\\n\\n- 空白「修改意见」确认 agent 选择，仅对仍可达且前置成立的节点有效。\\n- 非空意见作为答案或约束；可唯一确定时替换选择，否则重开节点。\\n- 补充说明按事实、约束或决策纳入 tree；HTML 注释不算内容，事实继续取证，判断进入新 frontier。\\n\\n全部反馈已纳入或因前置失效而排除、新事实已查明或标 blocker、新 frontier 已计算时，本轮评价完成。空反馈确认草案；有新 frontier 时返回第 1 节。\\n\\n## 3. 收口\\n\\n拷问收敛、未知事实已查明，审阅文件包含全部问题、推荐与选择及理由、修改意见，末尾保留「补充说明」。复述结论并获用户明确确认共同理解后完成；确认前工作保持在设计范围。\\n\\n领域变更按 [DOMAIN.md](DOMAIN.md) 同步并通过校验；其他讨论仅直接维护审阅文件。\\n\\n## 审阅模板\\n\\n```markdown\\n# {中文工作名}\\n\\n## 第 {round} 轮\\n\\n### ❓ Q{question} — {标题}\\n\\n- 问题：{问题与互斥选择}\\n- 前置问题：{Q 编号或无}\\n- 下游边界：{该答案会改变什么}\\n- ➡️ 推荐答案：{推荐}\\n- 推荐理由：{关键理由}\\n- 选择答案：{选择}\\n- 选择理由：{关键理由}\\n- 修改意见：\\n\\n<!-- 每题重复以上结构，编号在整个 quest 内递增；按轮追加，补充说明始终位于末尾。 -->\\n\\n## 补充说明\\n\\n<!-- 填写所有问题均未涉及的用户补充说明；没有则留空。 -->\\n```\\n"},{"path":"references/skills/questing/DOMAIN.md","content":"# 领域文档\\n\\n仅在讨论需要改变领域模型或 ADR 时使用；读取领域语言供其他任务使用不触发维护。\\n\\n1. **定域**：完整读取 领域布局与定位规则（`<nano-flow-skill-root-dir>/references/DOMAIN.md`），从 `CONTEXT-MAP.md` 定位所有相关业务域，读取对应 `CONTEXT.md` 与 ADR。归属仍需判断时，将带推荐答案的问题纳入 design tree；相关域与跨域关系均确定时完成。\\n2. **拷问**：以现有 glossary 与 ADR 约束设计。术语冲突时区分 canonical term 与新概念；关系与规则含糊时用 scenario 和 edge case 暴露边界；用代码核对用户对现状的描述，将矛盾纳入 frontier。环境事实由 agent 查明，trade-off 与领域选择按设计分支形成 draft 并由用户评价。\\n3. **维护语言**：已确认的新域、术语与跨域关系按 [Context 格式](#context-格式) 在成立的同一轮就地更新。每项内容只有一个权威位置，map 链接可解析，canonical term 与 `_Avoid_` 互不冲突时完成。\\n4. **记录 ADR**：架构形态、跨域集成、技术锁定、scope owner 或其他长期 trade-off，按 [ADR 格式](#adr-格式) 的资格门槛逐项判断；达标的决策只写入唯一 owner 一次，理由与已确认取舍一致时完成。\\n5. **校验**：代码与口头模型的矛盾已解决或明确记录、用户确认共同理解，且从工作区根执行 `node <nano-flow-skill-root-dir>/scripts/check-domain.mjs .` 通过时完成。\\n\\n## Context 格式\\n\\n### 业务域 CONTEXT.md\\n\\n```md\\n# {Context 名称}\\n\\n{一到两句话说明该 context 的领域职责。}\\n\\n## Language\\n\\n**{Canonical term}**:\\n{一到两句话定义它是什么}\\n_Avoid_: {会造成歧义的同义词}\\n```\\n\\n- 一个概念选择一个 canonical term，把会造成歧义的同义词列入 `_Avoid_`。\\n- 定义说明概念是什么，保持一到两句话；规则与实现细节进入其他权威产物。\\n- 只收录当前业务域特有的语言；通用编程概念留在代码或工程文档。\\n- 自然形成多个概念簇时使用 subheading；单一 cohesive area 保持 flat list。\\n\\n### CONTEXT-MAP.md\\n\\n```md\\n# Context Map\\n\\n## Contexts\\n\\n- [Ordering](./docs/ordering/CONTEXT.md) - 接收并跟踪 customer orders。\\n- [Billing](./docs/billing/CONTEXT.md) - 生成 invoices 并处理 payments。\\n\\n## Relationships\\n\\n- **Ordering → Billing**: Ordering 发出 `OrderCompleted`；Billing 消费它并生成 invoice。\\n```\\n\\nmap 按领域布局维护索引与唯一跨域关系；新域同时创建 CONTEXT 与 map entry，链接可解析。没有跨域关系时省略 `Relationships`。\\n\\n## ADR 格式\\n\\nADR 按领域布局的 owner、路径与编号规则创建；目录在首份 ADR 出现时创建，跨域决策由其他域链接引用。\\n\\n### 资格门槛\\n\\n一项决策同时满足以下条件才成为 ADR：\\n\\n1. **Hard to reverse**：未来改变它有显著成本。\\n2. **Surprising without context**：只看实现无法理解为何这样选择。\\n3. **Real trade-off**：存在真实备选，并因明确理由选择其一。\\n\\n常见候选包括架构形态、跨域集成、带 lock-in 的技术选择、owner 与 scope 边界、刻意偏离常规路径的方案，以及代码不可见的外部约束。库的普通选用、易逆转偏好和没有备选的显然选择不形成 ADR。\\n\\n### 最小模板\\n\\n```md\\n# {决策的简短标题}\\n\\n{1-3 句话说明 context、决策与理由。}\\n```\\n\\nADR 可以只包含这个段落。下列内容仅在增加长期解释价值时添加：\\n\\n- `Status` frontmatter：`proposed | accepted | deprecated | superseded by ADR-NNNN`。\\n- `Considered Options`：被拒绝的备选值得未来读者记住。\\n- `Consequences`：存在不明显且重要的下游影响。\\n\\n创建前扫描 owner 域现有 ADR 的最大编号并递增 1。文件名、编号、owner、决策理由和引用均一致时完成。\\n"},{"path":"references/skills/questing/SKILL.md","content":"---\\nname: questing\\ndescription: 澄清想法、用户故事、计划或设计直到共同理解，并按需维护领域语言与决策时使用。\\n---\\n\\n# Questing\\n\\n按任务与已有产物选择分支，复用仍成立的结论和确认：\\n\\n| 分支     | 触发与流程                                                                                                               |\\n| -------- | ------------------------------------------------------------------------------------------------------------------------ |\\n| `story`  | 生成或打磨用户故事：按 [STORY.md](STORY.md) 由用户逐轮澄清，维护 `story.md`                                              |\\n| `domain` | 拷问计划、决策或设计：按 [DESIGN.md](DESIGN.md) 由 agent 先回答、用户统一评价；涉及领域变更时同步 [DOMAIN.md](DOMAIN.md) |\\n\\n故事澄清后继续设计；已有故事从设计开始。所涉及分支的产物与完成标准均成立、确认结论写入各自唯一权威位置时返回。\\n"},{"path":"references/skills/questing/STORY.md","content":"# 用户故事\\n\\n使用 **3C**：`story.md` 是 card，分轮访谈形成 conversation，可判定验收形成 confirmation。\\n\\n## 1. 定位 Plan\\n\\n按 领域定位规则（`<nano-flow-skill-root-dir>/references/DOMAIN.md`） 确定 owner，读取相关 CONTEXT、ADR 与已有 Plan；按 [故事模板](#故事模板) 创建或续写：\\n\\n```text\\ndocs/{domain-name}/plans/active/YYYY-MM-DD-中文工作名/story.md\\n```\\n\\nowner、Plan 路径、原始想法和相关现有产物均已确定时完成。候选决策只进入 `story.md`；领域术语与 ADR 由 `domain` 分支确认后维护。\\n\\n## 2. 逐轮澄清\\n\\n按 Design [tree](DESIGN-TREE.md) 推进，将角色、用户结果、收益、边界、验收与未知项纳入问题；每轮由用户回答后再继续，问题使用以下格式：\\n\\n```markdown\\n❓ **Q1 - {问题标题}**：{问题；需要时列出互斥选择}\\n\\n➡️ **建议**：{推荐答案与关键理由}\\n```\\n\\n每轮就地更新 `story.md`：已确认角色和完整用户结果进入对应章节，较大结果归入 epic；未知项进入「迷雾」，澄清后迁移；使用的产物记入「上下文」。\\n\\n用户确认共同理解前，工作限于取证、访谈与维护 `story.md`。拷问收敛，且已复述故事地图并获用户确认时完成。\\n\\n## 3. 闭合故事集\\n\\n核对每条故事具有唯一且单调递增的 `US-NNN`、明确角色与收益、至少一项可判定验收；迷雾为空或保留项均获用户明确接受；每个原始意图恰好映射到故事或已接受的非范围。\\n\\n从工作区根运行 `node <nano-flow-skill-root-dir>/scripts/check-domain.mjs .`。校验通过且用户确认故事集覆盖原始想法时完成。\\n\\n## 故事模板\\n\\n属于 epic 的故事使用四级标题；独立故事使用三级标题，不创建空壳 epic。\\n\\n```markdown\\n# {工作名}\\n\\n## 原始想法\\n\\n{用户的最初表述，保留原话}\\n\\n## 角色\\n\\n- **{角色名}**：{是谁、处境与工作方式}\\n\\n## 故事\\n\\n### {Epic 标题}\\n\\n{这组故事共同完成什么}\\n\\n#### US-001 {故事标题}\\n\\n作为 {角色}，我 {想要}，以便 {收益}。\\n\\n- [ ] {可判定的验收结果}\\n\\n### US-002 {独立故事标题}\\n\\n作为 {角色}，我 {想要}，以便 {收益}。\\n\\n- [ ] {可判定的验收结果}\\n\\n## 迷雾\\n\\n{尚未澄清的空白；澄清后迁移到权威章节}\\n\\n## 上下文\\n\\n{通过路径或 URL 引用生成故事时使用的现有产物；域内文档使用相对路径}\\n```\\n\\n模板可扩展：仅当内容无法归入现有章节，且缺少它会损失执行或验收信息时新增中文章节。\\n"},{"path":"references/skills/simplify/agents/openai.yaml","content":"policy:\\r\\n  allow_implicit_invocation: false\\r\\n"},{"path":"references/skills/simplify/SKILL.md","content":"---\\nname: simplify\\ndescription: 对整个工作区或指定范围的增量与存量代码做简化审查和清理，覆盖复用、删减、深度与性能；先读取全部领域 ADR 与 Plan。\\ndisable-model-invocation: true\\n---\\n\\n# Simplify\\n\\n**证据**：每个候选有 file:line、消费方证据和现状成本；只有“看起来复杂”的 nit 不入选。\\n\\n**删减**：deletion over addition，以保持行为、约束并降低复杂度为成功标准；净删除量只作辅助证据。正确性审查归 `/code-review`，调查中发现的真实 bug 单独显著报告。\\n\\n## 1. 确定范围\\n\\n默认整个工作区的 production 代码；用户可缩至域、目录或文件。未交付的工作区/branch 增量与存量统一评判，排除构建产物、依赖和生成物。\\n\\n范围及排除项明确时完成；用户只要报告时，以建议呈现为交付，后续应用和修改后验证不适用。\\n\\n## 2. 读取领域约束\\n\\n按 DOMAIN.md（`<nano-flow-skill-root-dir>/references/DOMAIN.md`） 定位范围内所有业务域，读取 map、各域 `CONTEXT.md`、**全部 ADR 与 Plan**，以及适用 `AGENTS.md` 和 `/code-spec`。\\n\\n- ADR 与 CONTEXT 保护 intentional design、seam、契约和术语。候选与 ADR 冲突时列出冲突及重议理由，交用户决定。\\n- active/reference Plan 约束方向：保留未交付 requirement 和已确认路线；archived Plan 只解释废弃历史。\\n\\n全部相关约束已读取、受保护设计已列出时完成。\\n\\n## 3. Survey\\n\\n按域或顶层目录分区，并行派遣 subagents；每人取得一个分区、完整约束及下列角度。用户指定 focus 时只调查对应角度。单目录以内直接调查；无 subagent 能力时按分区顺序执行并在报告说明。\\n\\n| 角度     | 寻找                                                                                                                                   |\\n| -------- | -------------------------------------------------------------------------------------------------------------------------------------- |\\n| **复用** | 重复实现、可用 stdlib/平台/已安装依赖替代的手写逻辑；点名复用对象及位置                                                                |\\n| **删减** | dead code、speculative generality、单实现抽象、转发 wrapper、冗余状态、复述代码的注释及更短等价形态                                    |\\n| **深度** | generic path 的单调用方特例、层叠 workaround、绕开根因的 wrapper；深层修复只标记                                                       |\\n| **性能** | 冗余计算/读取/调用、N+1、独立操作串行、启动或请求热路径重活、过宽读取、无界增长、未清理 listener/handle；TOCTOU 改为直接操作并处理错误 |\\n\\n按 **Chesterton\'s fence**，删除前用 blame、消费方检索和领域约束核对存在理由；理由不明标 low，猜测项丢弃。只有测试/文档消费且行为不承重是强候选；删除生产消费者依赖的行为属于 feature decision，保持行为的结构简化属于 cleanup。\\n\\n每个分区覆盖全部选定角度后才结束；每项均有位置、消费方与成本证据。\\n\\n## 4. 汇总与应用\\n\\n发现格式：`file:line → 问题 → 现状成本 → 建议 | confidence: high/medium/low | risk: SAFE/CAREFUL/RISKY`。\\n\\n合并去重，丢弃证据不足项。冲突按“正确性 > 用户 focus > 可读性与复用 > 微优化”裁决；微优化仅在已确认热路径上优先。互斥且均可行时选改动较小者，备注另一方案。\\n\\n| Risk        | 定义                                                                          | 应用                                                   |\\n| ----------- | ----------------------------------------------------------------------------- | ------------------------------------------------------ |\\n| **SAFE**    | 已证明行为不变，如无生产消费方的 dead code、未使用 import                     | 直接应用，运行 targeted tests                          |\\n| **CAREFUL** | extract、inline、局部重命名、拍平嵌套等语义保持修改                           | 逐文件应用并运行 targeted tests，失败回退该条          |\\n| **RISKY**   | 公共契约（导出名/API/配置键）、行为可能改变、受保护设计、并发化或访问模式重构 | 只呈现风险、覆盖情况及新 issue 或 `/questing` 跟进建议 |\\n\\n只报告模式完成呈现即可；应用模式限于发现及修复所需最小邻域，SAFE/CAREFUL 均应用或回退、RISKY 逐条呈现时完成。\\n\\n## 5. 验证与收口\\n\\n有修改时运行触及文件的 targeted tests 和仓库 linter/typecheck；失败则单独回退对应修复并报告。有意保留的全局锁、O(n²) 扫描、naive heuristic 等上限，按 `/code-spec` 注明原因及升级触发条件。\\n\\n按分区、角度、tier 报告发现与建议、已应用项、跳过及理由、净删除量；顺序替代并行时说明。适用验证通过且报告完整时完成。\\n\\n`/code-spec` 要求的校验与错误处理、安全措施、用户明确要求均保留；深层或超出本 pass 范围的重构通过 RISKY 跟进。\\n"},{"path":"references/skills/to-issues/SKILL.md","content":"---\\nname: to-issues\\ndescription: 跨会话推进或需要持久化检查点时，建立和维护可恢复的 spec、设计 frontier 与 tracer-bullet issue 图。\\nargument-hint: \\"要持久化什么长任务?\\"\\n---\\n\\n# To Issues\\n\\n完整读取 DOMAIN.md（`<nano-flow-skill-root-dir>/references/DOMAIN.md`），遵循领域布局与 Plan 生命周期。\\n\\n## 判断是否跳过\\n\\n需持久化推进则推荐继续，否则推荐跳过，等待用户确认；\\n\\n## 建立或维护\\n\\n写入前完整读取 [TEMPLATE.md](TEMPLATE.md)，以其模板与扩展规则为权威。\\n\\n1. **定域与取证**：从 map 定位一个 owner 域，读取 CONTEXT、相关 ADR/Workflow 和已有 story、spec、issue、commit/diff。跨域时先确认关系并选主域，或分域拆分；归属和相关事实查明时完成。\\n2. **就地落盘**：将已确认结论写入 spec 与 issue，按下方 tracer-bullet 规则拆分。新事实更新 spec，新工作新增 issue；尚不能精确表述的 frontier 留在「待定」，执行中 issue 的边界保持稳定。结论均有权威归属时完成。\\n3. **确认**：按反馈迭代，用户确认边界与依赖图正确时完成。\\n4. **校验交接**：从工作区根运行 `node <nano-flow-skill-root-dir>/scripts/check-domain.mjs .`，通过下方完成门槛后交接。\\n\\n## Tracer bullets\\n\\n- 每个 issue 对应一个完整用户结果或业务能力，只贯穿所需层级。\\n- 直接依赖成立后可独立实现、交付和验收；每条依赖说明原因与消费的产物/契约。\\n- 最小验收信号是一个可独立判定的结果。\\n- 降低后续实现难度的 prefactoring 排最前。\\n- 唯一例外是大范围机械重构：expand → 按影响面分批 migrate（每批一个 issue）→ contract 删除旧形态。\\n\\n**完成门槛**：范围无遗漏、每项交付责任唯一归属、依赖图有根且无环、用户确认、校验通过。新建 issue 均为 `pending`，维护时保留既有执行状态；仅凭领域文档、Plan 与 Flow 运行态即可恢复。\\n"},{"path":"references/skills/to-issues/TEMPLATE.md","content":"# Plan 文档模板\\n\\n## spec.md 模板\\n\\n```markdown\\n---\\nstatus: pending\\n---\\n\\n# {工作名}\\n\\n## 问题\\n\\n{用户要得到的结果, 已知约束}\\n\\n## 方案\\n\\n{保持在设计层级}\\n\\n## 已排除的备选\\n\\n- {方案}: {拒绝理由}\\n\\n## 实施决策\\n\\n{模块, 接口, schema, 契约等设计层级内容; 决策密度高的片段(state machine, schema, type shape)可内联并注明出处}\\n\\n## 工作环境\\n\\n{执行该工作所需的环境信息: 例如项目管理工具, 本地开发环境, CI/CD 流水线, 运行时环境, 三方服务等}\\n\\n## 范围\\n\\n{做什么}\\n\\n## 非范围\\n\\n{不做什么}\\n\\n## 待定\\n\\n{尚不能精确表述为 issue 的未决问题、已知选项或证据、恢复条件; 澄清后 graduate 为 issue}\\n\\n## 上下文\\n\\n{通过路径或 URL 引用已有产物: PRD, story, spec, ADR, workflow, commit, diff 等; 域内引用使用从当前文件计算的相对路径}\\n\\n## Issue\\n\\n| #   | Issue                  | 状态    | 阻塞于 | 下一步         |\\n| --- | ---------------------- | ------- | ------ | -------------- |\\n| 01  | [{标题}](01-{标题}.md) | pending | —      | /code-delivery |\\n```\\n\\n## issue 模板\\n\\n```markdown\\n---\\nstatus: pending\\nblocked_by: []\\n---\\n\\n# {标题}\\n\\n## 交付\\n\\n{用户可感知的结果}\\n\\n## 范围\\n\\n{做什么, 不做什么}\\n\\n## 直接依赖\\n\\n- {NN}: {原因}; 消费其 {产物或契约}\\n\\n## 验收\\n\\n- [ ] {可独立判定的最小结果}\\n\\n## 上下文\\n\\n- {通过路径或 URL 引用相关产物: PRD, story, spec, ADR, workflow, commit, diff 等; 域内引用使用从当前文件计算的相对路径}\\n\\n## 下一步\\n\\n{决策已澄清: /code-delivery; 仍需澄清: /questing}\\n\\n## 阻塞记录\\n\\n{仅 status 为 blocked 时保留: 障碍与解除条件}\\n\\n## 交付记录\\n\\n{完成登记前填入并保留: 交付物与验证证据链接}\\n```\\n\\n## 模板扩展\\n\\n模板可扩展：内容无法归入现有章节（**独特**），且缺少它会损失执行或验收信息（**必要**）时，才新增中文章节；否则归入现有章节或省略。\\n"},{"path":"references/skills/to-prototype/agents/openai.yaml","content":"policy:\\n  allow_implicit_invocation: false\\n"},{"path":"references/skills/to-prototype/LOGIC.md","content":"# 逻辑原型\\n\\n用自包含单文件 HTML 回答业务逻辑、状态转换或数据形状的问题，让非开发者自由操作并走查纸面上难以判断的场景。外观问题见 [UI.md](UI.md)。\\n\\n## 1. 写明问题\\n\\n编码前在 demo 顶部可见介绍区写明状态模型与待回答的问题，供用户随时核对。\\n\\n## 2. 隔离逻辑\\n\\n将逻辑放进单个 `<script>` 的小而纯的候选模块，按问题选择：\\n\\n- 离散事件与单个状态值：纯 reducer `(state, action) => state`。\\n- 需要检验哪些动作合法：显式状态与转换的状态机。\\n- 只有数据转换、无隐式当前状态：一组纯函数。\\n- 拥有持续内部状态：有清晰方法面的 class/module。\\n\\n选择最适合问题的形态，不以接入页面的便利决定。\\n\\n逻辑独立于 DOM 和 `document`，页面通过接口调用它，handler 不进入内部。复用遵循 [捕获与交付规则](SKILL.md#共同规则)。\\n\\n## 3. 构建 demo\\n\\n所有 HTML/CSS/JS 内联，无框架、打包器或服务器，双击即开并可分享。标签使用领域语言，文案遵循 [共同写作规则](SKILL.md#设计中的写作)。\\n\\n从上到下：\\n\\n1. **标题与说明**：重述要探索的问题。\\n2. **当前状态**：用有标签的面板渲染全部相关状态，每次点击刷新；有帮助时标出变化。\\n3. **自由操作**：每个动作一个始终可用的按钮，支持任意顺序尝试；点击执行对应动作并刷新状态。\\n4. **引导走查**：每场景一个页签，平实说明处境与观察点；步骤按顺序排列为真按钮，点击执行并前进。开始走查重置已知初态，保证可重跑。\\n\\n覆盖快乐路径、难推理的边界和一次理应非法的尝试。字体、间距与一个点缀色保持美观克制，不使用动画或噱头，任何装饰都不与状态和按钮争夺注意力。\\n\\n## 4. 交付与反馈\\n\\n提供文件或现场打开，供用户自由操作、走查并反馈不符合预期的行为；按反馈补充动作和场景。按 [证据收口与归档规则](SKILL.md#共同规则) 记录答案，保存完整 HTML 作为可重跑的实验依据。\\n"},{"path":"references/skills/to-prototype/SKILL.md","content":"---\\nname: to-prototype\\ndescription: 构建一次性原型，回答逻辑或状态模型是否顺手、UI 应呈现何种外观的设计问题。\\nargument-hint: \\"要回答的问题是什么? (逻辑手感还是 UI 外观)\\"\\ndisable-model-invocation: true\\n---\\n\\n# 原型\\n\\n原型是**回答一个问题的一次性代码**。按用户输入与周围代码选择：\\n\\n- 逻辑/状态模型的手感 → [LOGIC.md](LOGIC.md)：可分享的单文件 HTML，自由操作与分页签引导走查，让非开发者驱动边界用例。\\n- UI 外观 → [UI.md](UI.md)：同一路由的多个独特变体，用 URL search param 与底部浮动栏切换。\\n\\n问题含糊且用户在场时询问；联系不上时按代码默认匹配（后端模块 → 逻辑，页面/组件 → UI），在原型顶部声明假设。\\n\\n## 共同规则\\n\\n1. **一次性**：放在所服务模块或页面旁，名称明确标记原型；UI 路由遵循项目约定。\\n2. **运行零门槛**：UI 由任务 runner 一条命令启动；逻辑 demo 双击单个 HTML 即开。\\n3. **内存状态**：默认不持久化；问题涉及数据库时用 scratch DB 或清楚标记“PROTOTYPE，随手可删”的本地文件。\\n4. **快速取证**：手工走查，不写测试；错误处理以能跑为限，不做抽象。\\n5. **暴露状态**：每次动作或变体切换后打印或渲染全部相关状态。\\n6. **证据收口**：动手前写明问题与判断依据。可运行、约定场景或全部变体已走查、观察及访问入口已提供时完成交付；需用户判断则标「待反馈」。观察支撑结论且所需判断已确认时，问题才算回答。\\n7. **捕获与交付**：原型作为 primary source 提交到一次性分支，不进 main；在 issue 或 commit 记录问题、观察、结论/待反馈状态与指针。正式实现吸收已确认决策：逻辑模块可作候选代码复用，UI 按选定设计实现，均完成项目规范、审查与测试；手工走查只证明实验结果。\\n\\n## 设计中的写作\\n\\n文案与间距、色彩同样需要设计：先明确要说什么，以及如何帮助用户走完整个体验。\\n\\n- **用户视角**：使用用户认知和控制的领域名称，具体、平实地说明功能，避免推销与抖机灵。\\n- **动作一致**：主动语态，控件说清结果，同一动作全程同名。\\n- **失败与空态**：用界面自身的声音说明错误与修复入口；空态邀请行动，不道歉或渲染情绪。\\n- **语域**：对话式、平实动词、sentence case、无填充词，符合品牌与受众。\\n- **单一职责**：标签标注、示例演示，每个元素只承担自己的角色。\\n"},{"path":"references/skills/to-prototype/UI.md","content":"# UI 原型\\n\\n在同一路由比较多个 UI 变体，选定或组合后丢弃其余。逻辑/状态问题见 [LOGIC.md](LOGIC.md)；文案遵循 [共同写作规则](SKILL.md#设计中的写作)。\\n\\n## 选择宿主\\n\\n在真实 header、sidebar、数据与密度中评估：\\n\\n- **A：挂在既有页面（首选）**。保留数据获取、params、鉴权于切换逻辑之上，只切换渲染子树；适用于现有页面及自然属于它的新区块或步骤。\\n- **B：新建页面**。仅限没有合理宿主的新顶层界面/流程，按项目路由约定创建一次性页面。\\n\\n## 设计原则\\n\\n以小型设计工作室负责人标准，为每个变体明确针对简报的配色、字体与布局，承担一处有理由的美学冒险。\\n\\n- **主题**：简报未定时先明确主题、受众、页面唯一职责与理由；参考用户偏好、项目与过往设计，使用真实简报内容、材料和行话。\\n- **Hero 是论点**：用主题特征开场，选择标题、图、动画或互动；大数字配标签、统计加渐变仅在确实最优时使用。\\n- **字体即个性**：刻意搭配 display/body，确定 scale、字重、字宽与间距。\\n- **结构即信息**：编号、eyebrow、分隔线与标签有真实依据；编号只用于有意义的顺序。\\n- **动效服务主题**：选择加载、滚动、悬停或环境编排；集中表达，控制零散特效。\\n- **复杂度匹配愿景**：极繁执行繁复，极简精确处理间距、字体和细节。\\n- **文案**：缺失内容自行补齐，遵循共同写作规则并体现简报特征。\\n\\n## 1. 明确问题与变体\\n\\n默认 3 个变体，上限 5 个。在原型位置或文件顶部用一行注释写明问题、数量与计划，供用户反驳。\\n\\n## 2. 设计计划\\n\\n简报指定方向优先；留白处做独特选择，兼顾熟悉做法与实验。校准常见模板风格（暖奶油/衬线/赤陶、近黑/单亮色、broadsheet/细线/零圆角/多栏），仅在契合主题时采用。\\n\\n每个变体先写紧凑 token 计划：4–6 个命名 hex 色值；至少 display/body 两个字体角色，按需加数据/说明字体；一句布局概念和 ASCII 线框图；一个体现简报的签名元素。\\n\\n对照简报修订通用默认项并说明理由，可用相似 prompt 检查方案是否趋同。确认相对独特性后编码；构思迭代尽量内部完成，有较高把握时再展示。\\n\\n## 3. 生成变体\\n\\n按计划实现全部颜色与字体，符合页面目的、数据和项目组件/样式体系，清晰导出 `VariantA`、`VariantB` 等组件。\\n\\n- 布局、信息层级与主要 affordance 实质不同；仅换色不算。太相似时给一个变体增加明确结构约束后重做。\\n- 可共享 Header，各自拥有 Layout。\\n- 默认只读；确需改数据时接 stub。\\n- 检查 CSS specificity、class 叠加，以及 section 间 padding/margin。\\n\\n## 4. 接入切换\\n\\n路由读取 `?variant=`，默认 A，将 data 传给对应变体，并渲染接收全部 keys 与当前 key 的 `PrototypeSwitcher`。B 使用 `/prototype/<name>` 一次性路由，并遵循项目约定。\\n\\n共享 UI 位置放一个切换栏供两种形态复用，固定屏幕底部中央：\\n\\n- 左箭头 / 当前标签 / 右箭头，循环切换；标签显示 key，按需附导出名。\\n- 使用框架 router 更新 search param，支持分享和刷新。\\n- `←`/`→` 同样切换；焦点在 input、textarea、contenteditable 时保持编辑行为。\\n- 用高对比胶囊与柔和阴影等形态区别于被评估页面。\\n- 以 `process.env.NODE_ENV !== \'production\'` 或等价检查隐藏生产环境的切换栏。\\n\\n## 5. 交付与吸收\\n\\n提供 URL 和全部变体 keys，接受组合反馈。按 [证据收口与归档规则](SKILL.md#共同规则) 记录选择、理由和整套变体。\\n\\n正式实现时：A 将胜者折入既有页面，移除落选变体与切换栏；B 将胜者提升为正式路由，移除一次性路由与切换栏。main 只保留正式实现。\\n\\n## 质量下限\\n\\n大胆集中于签名元素，周围保持克制，删去不服务简报的装饰。覆盖移动端、可见键盘焦点与 reduced motion；持续自评，环境支持时截图。尝试新做法，有便捷记录处时留下经验。\\n"},{"path":"references/skills/verifying/SKILL.md","content":"---\\nname: verifying\\ndescription: 需要验证交付主张，以可复核门禁证据判定 passed、failed 或 blocked 时使用。\\n---\\n\\n# Verifying\\n\\n**证据链**：交付主张 → 适用门禁 → 实际结果 → 结论。失败时进入**最小循环**: 失败 → 证据定位 → 最小修复 → 重验.\\n\\n## 证据链\\n\\n1. **明确主张**：确定变更、受影响单元、外部契约、消费者和目标环境。每项主张均映射到影响面，未知与非范围已明确时完成。\\n2. **选择门禁**：从工作区声明的格式、静态检查、测试、构建、运行态和消费者路径中选取足以支撑主张的最小集合。每项均有事实来源、执行入口和通过条件时完成。\\n3. **执行门禁**：按依赖顺序从最早缺少可信证据处开始；旧证据仅在目标、版本、配置和前置仍适用时复用。每项均有实际结果、可信证据或明确阻塞前置时完成。\\n4. **最小循环**：从最早失败门禁取证，在授权范围内做最小修复，从最早受影响门禁重验；仍失败则以新证据继续。每轮失败、修复与重验一一对应，受影响证据链通过或明确 `blocked` 时完成。\\n5. **闭合结论**：先给结论，再记录各门禁结果、关键证据、未验证范围和剩余风险。结论不超出证据覆盖范围，另一执行者可复现失败或阻塞项时完成。\\n\\n## 结论门禁\\n\\n- `passed`：范围内适用门禁均实际通过，或有仍适用于当前目标的可信通过证据；修复影响的门禁以修复后的重验结果为准。\\n- `failed`：必要前置满足，门禁结果与主张矛盾。\\n- `blocked`：必要门禁因前置无法满足而没有结果；记录缺失条件和恢复入口。\\n\\n局部通过只支持对应范围，未验证部分保持显式。\\n"},{"path":"references/skills/writing-for-agents/SKILL-MECHANICS.md","content":"# Skill mechanics\\n\\n编写 skill 时使用；通用文档规则见 [SKILL.md](SKILL.md)。\\n\\n## Invocation\\n\\n选择调用方式是在 context load 与 cognitive load 之间取舍：\\n\\n| 方式              | 可达性与成本                                             | Description                                                       |\\n| ----------------- | -------------------------------------------------------- | ----------------------------------------------------------------- |\\n| **Model-invoked** | agent 可自行到达，用户仍可点名；承担常驻 context load    | 面向 model，包含独立触发分支；也可承载其他 skill 共用的 reference |\\n| **User-invoked**  | 由用户点名进入，依赖人类索引；不自动加载到 model context | 面向人类的一行摘要，省去自动触发列表                              |\\n\\nagent 或其他 skill 需要自主到达时选择 model-invoked；始终由人触发时选择 user-invoked。保留已有调用策略。\\n\\n按宿主配置：支持该 frontmatter 的宿主使用 `disable-model-invocation: true` 关闭自主调用；本仓库的 Codex 配置同时在 `agents/openai.yaml` 使用 `policy.allow_implicit_invocation: false`。默认 model-invoked 时省略关闭项。具体发现与调用机制以目标宿主为准，普通文件 pointer 与 skill 自动调用须分开判断。\\n\\n两个 user-invoked skills 共用的 reference 放在 skill system 外的普通文件中，不归属其中任一 skill；双方通过 pointer 读取，避免依赖彼此的自动调用入口。\\n\\n## Splitting by invocation\\n\\n出现值得独立触发的 leading word，或其他 skill 需要独立到达该能力时，才拆为 model-invoked skill；独立可达性的收益须抵偿新增 description 的常驻成本。\\n\\n## Router skills\\n\\nuser-invoked skills 多到难以记住时，可用一个 user-invoked router 列出名称与选择条件，让用户只记一个入口。它提示用户选择；目标 skill 的显式调用策略仍然有效。\\n"},{"path":"references/skills/writing-for-agents/SKILL.md","content":"---\\nname: writing-for-agents\\ndescription: 编写或优化 skill、AGENTS.md、CLAUDE.md 及其引用文档时使用；检查 context pointers、信息层级、完成标准与 pruning。\\n---\\n\\n让 agent 稳定采用同一流程，同时允许结果随任务变化。编写 skill 时另读 [SKILL-MECHANICS.md](SKILL-MECHANICS.md)，处理 frontmatter、invocation 与 router。\\n\\n## Context pointers\\n\\n**Context pointer** 为 context 外的材料命名，并说明何时读取。skill description 和 `AGENTS.md` 中的文档引用都是 pointer。**Branch** 是需要不同处理路径的独立情况。\\n\\n可达性取决于 pointer 的措辞。必需材料未被可靠读取时，先强化 pointer；无效后才 inline。始终加载的 pointer 每轮都消耗 context，应比正文更严格 pruning：\\n\\n- **Front-load the leading word**：把触发概念放在前面。\\n- **One trigger per branch**：合并同一分支的同义触发，保留独立分支。\\n- 只写材料与触发条件，删除正文已有的身份说明。\\n\\n## The two loads\\n\\n- **Context load**：始终加载的指令、description 和 pointer 消耗的 tokens 与注意力，无论是否触发。\\n- **Cognitive load**：人类记住有哪些文档、何时使用它们的成本。在需要人类判断处投入，在其余位置消除。\\n\\n只能通过 pointer 到达的材料，常驻成本仅为 pointer；完全没有 pointer 的材料依赖人类索引。拆分文档会增加其中一种成本，收益须足以抵偿。\\n\\n## Information hierarchy\\n\\n文档可由顺序执行的 **steps**、按需查阅的 **reference** 或两者组成。按即时需要安排层级：\\n\\n1. **In-file step**：执行主线。\\n2. **In-file reference**：文件内的定义、规则与事实；同级规则组成扁平集合是合理结构。\\n3. **Disclosed reference**：独立文件，通过带触发条件的 pointer 读取；可位于同目录或外部。\\n\\n**Progressive disclosure** 保护主线：所有分支都需要的内容 inline，只有部分分支需要的内容下沉。下沉过少会埋没步骤，下沉过多会隐藏必需材料；按分支需要决定。\\n\\n**Co-location** 决定同层内容如何聚合：把同一概念的定义、规则与 caveats 放在一起。含义分散是 scattering；含义重复是 duplication。\\n\\n**Sprawl** 指内容虽各自有效，整体仍因过长而稀释注意力。按 branch 或 sequence 下沉 reference，使每条路径只携带所需内容。\\n\\n## Loops and workflows\\n\\n**循环（loop）** 是反复出现且有可辨认起止边界的活动。\\n\\n**工作流（workflow）** 是指导循环每次运行的规格；可规定固定步骤、提供现场派生步骤的上下文，或混合两者。\\n\\n一份工作流只规格化一个循环，结构由循环决定。先明确触发、输入、前置条件、结束边界、输出与完成证据，再组织步骤和上下文。\\n\\n## Steps and completion criteria\\n\\n每个 step 以 **completion criterion** 结束；最强的 criterion 可检查且穷尽：\\n\\n- **Clarity**：能区分 done 与 not-done。模糊界限会诱发 **premature completion**，可见的后续步骤（**post-completion steps**）又会拉动 agent 提前收尾。先 **sharpen the bound**；只有界限仍模糊且已观察到赶进度时，才拆分 sequence。\\n- **Demand**：措辞要求的挖掘深度（**legwork**）。“每个修改过的 model 都已核对”比“生成变更清单”要求更完整。Demand 同样适用于 reference：逐条应用全部适用规则，无须另造步骤。\\n\\n## When to split\\n\\n- **By sequence**：拆分会拉动提前收尾的后续步骤。隐藏只有跨越真实 context boundary（hand-off 或 subagent dispatch）才有效；inline call 仍保留后续步骤。合并 sequence 也会重新暴露这种拉力。\\n- **By invocation**：独立触发是否值得增加常驻 description，见 [SKILL-MECHANICS.md](SKILL-MECHANICS.md)。\\n\\n## Leading words\\n\\n**Leading word** 用紧凑概念锚定行为。优先选择已有概念（如 _lesson_、_fog of war_、_tracer bullets_），调用 model 的 priors；自造词需自行承担定义成本。\\n\\n在正文中用它锚定执行，在 pointer 中锚定 invocation；让 prompt、文档和代码共享同一术语。重复 token，积累分布式定义，避免重复解释。逐项寻找可由一个概念替代的句子或重复属性：\\n\\n- “快速、确定、低开销” → _tight_ loop。\\n- “信得过的 loop” → _red_：loop 是否在目标 bug 上实际失败。\\n\\n**Prompt positive**：直接陈述目标行为。否定句会激活被禁止的行为；只有无法正向表达的 hard guardrail 才保留禁令，并配上正向目标。\\n\\n## Pruning\\n\\n- **Single source of truth**：每个含义只有一个权威位置，使行为变更成为单点编辑。Duplication 增加 tokens、维护成本，并夸大规则在层级中的权重。\\n- **Environment** 也是事实源：`package.json` scripts、配置、目录与 `--help` 可直接查明的内容属于 lookup。文档重述是 cache，仅在 lookup 成本高时保留；优先记录环境无法解释的约定、理由和陷阱。\\n- **Relevance**：逐行检查是否仍服务当前文档。无关说明、应下沉的分支和过时规则都需处理；持续 pruning，避免过时层积成 **sediment**。\\n- **No-ops**：相较 model 默认行为没有改变的指令，删除整句。判断依赖具体 model，应以运行文档解决分歧。过弱的 leading word 也可能是 no-op，应换成能改变行为的词（如从 _be thorough_ 到 _relentless_）。\\n"},{"path":"scripts/check-domain.mjs","content":"#!/usr/bin/env node\\r\\n\\r\\nimport fs from \\"node:fs\\";\\r\\nimport path from \\"node:path\\";\\r\\nimport { fileURLToPath } from \\"node:url\\";\\r\\n\\r\\nimport {\\r\\n  deriveSpecStatus,\\r\\n  ISSUE_STATUSES,\\r\\n  parseFrontmatter as parsePlanFrontmatter,\\r\\n  parseIssueDependencies,\\r\\n} from \\"./plan-document.mjs\\";\\r\\n\\r\\nconst LIFECYCLES = new Set([\\"active\\", \\"reference\\", \\"archived\\"]);\\r\\nconst SPEC_STATUSES = new Set([\\"pending\\", \\"in_progress\\", \\"completed\\"]);\\r\\nconst HAN_PATTERN = /\\\\p{Script=Han}/u;\\r\\n\\r\\nconst relativePath = (rootDir, targetPath) =>\\r\\n  path.relative(rootDir, targetPath).replaceAll(\\"\\\\\\\\\\", \\"/\\");\\r\\n\\r\\nconst addError = (errors, rootDir, targetPath, message) => {\\r\\n  errors.push(`${relativePath(rootDir, targetPath)}: ${message}`);\\r\\n};\\r\\n\\r\\nconst readText = (targetPath, errors, rootDir) => {\\r\\n  try {\\r\\n    return fs.readFileSync(targetPath, \\"utf8\\");\\r\\n  } catch (error) {\\r\\n    addError(\\r\\n      errors,\\r\\n      rootDir,\\r\\n      targetPath,\\r\\n      `读取失败: ${error instanceof Error ? error.message : String(error)}`,\\r\\n    );\\r\\n    return null;\\r\\n  }\\r\\n};\\r\\n\\r\\nconst readEntries = (targetPath, errors, rootDir) => {\\r\\n  try {\\r\\n    return fs.readdirSync(targetPath, { withFileTypes: true });\\r\\n  } catch (error) {\\r\\n    addError(\\r\\n      errors,\\r\\n      rootDir,\\r\\n      targetPath,\\r\\n      `枚举失败: ${error instanceof Error ? error.message : String(error)}`,\\r\\n    );\\r\\n    return [];\\r\\n  }\\r\\n};\\r\\n\\r\\nconst countLines = (content) => {\\r\\n  const normalized = content.replaceAll(\\"\\\\r\\\\n\\", \\"\\\\n\\");\\r\\n  return normalized.endsWith(\\"\\\\n\\")\\r\\n    ? normalized.slice(0, -1).split(\\"\\\\n\\").length\\r\\n    : normalized.split(\\"\\\\n\\").length;\\r\\n};\\r\\n\\r\\nconst parseFrontmatter = (content, targetPath, errors, rootDir) => {\\r\\n  const parsed = parsePlanFrontmatter(content);\\r\\n  if (!parsed) {\\r\\n    addError(errors, rootDir, targetPath, \\"缺少 YAML frontmatter\\");\\r\\n    return new Map();\\r\\n  }\\r\\n  return parsed.fields;\\r\\n};\\r\\n\\r\\nconst parseDependencies = (rawValue, targetPath, errors, rootDir) => {\\r\\n  const parsed = parseIssueDependencies(rawValue);\\r\\n  if (parsed.kind === \\"valid\\") return parsed.dependencies;\\r\\n  if (parsed.kind === \\"missing\\") {\\r\\n    addError(errors, rootDir, targetPath, \\"frontmatter 缺少 blocked_by\\");\\r\\n    return [];\\r\\n  }\\r\\n  const detail =\\r\\n    parsed.kind === \\"invalid_json\\" ? parsed.detail : \'必须是两位稳定 ID 的 JSON 数组，例如 [\\"01\\"]\';\\r\\n  addError(errors, rootDir, targetPath, `blocked_by 无效: ${detail}`);\\r\\n  return [];\\r\\n};\\r\\n\\r\\nconst hasSection = (content, heading) => new RegExp(`^## ${heading}$`, \\"m\\").test(content);\\r\\n\\r\\nconst assertChineseDocument = (content, targetPath, errors, rootDir) => {\\r\\n  if (!HAN_PATTERN.test(content)) {\\r\\n    addError(errors, rootDir, targetPath, \\"正文必须包含中文\\");\\r\\n  }\\r\\n};\\r\\n\\r\\nconst isValidDate = (value) => {\\r\\n  const [year, month, day] = value.split(\\"-\\").map(Number);\\r\\n  const date = new Date(Date.UTC(year, month - 1, day));\\r\\n  const normalized = [\\r\\n    date.getUTCFullYear().toString().padStart(4, \\"0\\"),\\r\\n    (date.getUTCMonth() + 1).toString().padStart(2, \\"0\\"),\\r\\n    date.getUTCDate().toString().padStart(2, \\"0\\"),\\r\\n  ].join(\\"-\\");\\r\\n  return normalized === value;\\r\\n};\\r\\n\\r\\nconst parseIssueTable = (specContent) => {\\r\\n  const rows = new Map();\\r\\n  for (const line of specContent.split(/\\\\r?\\\\n/)) {\\r\\n    if (!line.startsWith(\\"|\\")) continue;\\r\\n    const cells = line\\r\\n      .slice(1)\\r\\n      .split(\\"|\\")\\r\\n      .map((cell) => cell.trim());\\r\\n    if (cells.length < 5 || !/^\\\\d{2}$/.test(cells[0]) || !ISSUE_STATUSES.includes(cells[2])) {\\r\\n      continue;\\r\\n    }\\r\\n    const link = cells[1].match(/^\\\\[[^\\\\]]+\\\\]\\\\(([^)]+\\\\.md)\\\\)$/);\\r\\n    if (!link) continue;\\r\\n    rows.set(cells[0], {\\r\\n      dependencies: cells[3].match(/\\\\d{2}/g) ?? [],\\r\\n      fileName: path.basename(link[1]),\\r\\n      status: cells[2],\\r\\n    });\\r\\n  }\\r\\n  return rows;\\r\\n};\\r\\n\\r\\nconst checkDependencyGraph = (issues, planPath, errors, rootDir) => {\\r\\n  const issueById = new Map(issues.map((issue) => [issue.id, issue]));\\r\\n  if (!issues.some((issue) => issue.dependencies.length === 0)) {\\r\\n    addError(errors, rootDir, planPath, \\"Issue 依赖图至少需要一个根节点\\");\\r\\n  }\\r\\n\\r\\n  for (const issue of issues) {\\r\\n    for (const dependency of issue.dependencies) {\\r\\n      const dependencyIssue = issueById.get(dependency);\\r\\n      if (!dependencyIssue) {\\r\\n        addError(errors, rootDir, issue.path, `blocked_by 引用了不存在的 Issue ${dependency}`);\\r\\n        continue;\\r\\n      }\\r\\n      if (Number(dependency) >= Number(issue.id)) {\\r\\n        addError(errors, rootDir, issue.path, `依赖 ${dependency} 必须排在 Issue ${issue.id} 之前`);\\r\\n      }\\r\\n      if (\\r\\n        [\\"in_progress\\", \\"blocked\\", \\"completed\\"].includes(issue.status) &&\\r\\n        dependencyIssue.status !== \\"completed\\"\\r\\n      ) {\\r\\n        addError(\\r\\n          errors,\\r\\n          rootDir,\\r\\n          issue.path,\\r\\n          `${issue.status} Issue 的直接依赖 ${dependency} 尚未 completed`,\\r\\n        );\\r\\n      }\\r\\n    }\\r\\n  }\\r\\n\\r\\n  const visiting = new Set();\\r\\n  const visited = new Set();\\r\\n  const visit = (issue) => {\\r\\n    if (visiting.has(issue.id)) return true;\\r\\n    if (visited.has(issue.id)) return false;\\r\\n    visiting.add(issue.id);\\r\\n    const cyclic = issue.dependencies.some((dependency) => {\\r\\n      const dependencyIssue = issueById.get(dependency);\\r\\n      return dependencyIssue ? visit(dependencyIssue) : false;\\r\\n    });\\r\\n    visiting.delete(issue.id);\\r\\n    visited.add(issue.id);\\r\\n    return cyclic;\\r\\n  };\\r\\n\\r\\n  if (issues.some((issue) => visit(issue))) {\\r\\n    addError(errors, rootDir, planPath, \\"Issue 依赖图存在环\\");\\r\\n  }\\r\\n};\\r\\n\\r\\nconst checkIssue = (issuePath, id, errors, rootDir) => {\\r\\n  const content = readText(issuePath, errors, rootDir);\\r\\n  if (content === null) return null;\\r\\n  assertChineseDocument(content, issuePath, errors, rootDir);\\r\\n  const frontmatter = parseFrontmatter(content, issuePath, errors, rootDir);\\r\\n  const status = frontmatter.get(\\"status\\");\\r\\n  if (!ISSUE_STATUSES.includes(status)) {\\r\\n    addError(errors, rootDir, issuePath, `status 必须是 ${ISSUE_STATUSES.join(\\" | \\")}`);\\r\\n  }\\r\\n  const dependencies = parseDependencies(frontmatter.get(\\"blocked_by\\"), issuePath, errors, rootDir);\\r\\n\\r\\n  for (const heading of [\\"交付\\", \\"范围\\", \\"直接依赖\\", \\"验收\\", \\"上下文\\", \\"下一步\\"]) {\\r\\n    if (!hasSection(content, heading)) {\\r\\n      addError(errors, rootDir, issuePath, `缺少「## ${heading}」章节`);\\r\\n    }\\r\\n  }\\r\\n  if (status === \\"blocked\\" && (!content.includes(\\"障碍\\") || !content.includes(\\"解除条件\\"))) {\\r\\n    addError(errors, rootDir, issuePath, \\"blocked Issue 必须记录障碍和解除条件\\");\\r\\n  }\\r\\n  if (\\r\\n    status === \\"completed\\" &&\\r\\n    (!/^## (交付记录|交付物与证据)$/m.test(content) || !content.includes(\\"证据\\"))\\r\\n  ) {\\r\\n    addError(errors, rootDir, issuePath, \\"completed Issue 必须记录交付物与验证证据\\");\\r\\n  }\\r\\n\\r\\n  return { id, path: issuePath, status, dependencies };\\r\\n};\\r\\n\\r\\nconst checkPlanLayout = (planPath, lifecycle, errors, rootDir) => {\\r\\n  const planName = path.basename(planPath);\\r\\n  const planNameMatch = planName.match(/^(\\\\d{4}-\\\\d{2}-\\\\d{2})-(.+)$/);\\r\\n  if (!planNameMatch || !isValidDate(planNameMatch[1]) || !HAN_PATTERN.test(planNameMatch[2])) {\\r\\n    addError(errors, rootDir, planPath, \\"Plan 目录名必须是 YYYY-MM-DD-中文工作名\\");\\r\\n  }\\r\\n\\r\\n  const entries = readEntries(planPath, errors, rootDir);\\r\\n  for (const entry of entries.filter((item) => item.isDirectory())) {\\r\\n    addError(errors, rootDir, path.join(planPath, entry.name), \\"Plan 目录内不允许嵌套目录\\");\\r\\n  }\\r\\n  const markdownFiles = entries.filter((entry) => entry.isFile() && entry.name.endsWith(\\".md\\"));\\r\\n  const hasStory = markdownFiles.some((entry) => entry.name === \\"story.md\\");\\r\\n  const hasSpec = markdownFiles.some((entry) => entry.name === \\"spec.md\\");\\r\\n  if (!hasStory && !hasSpec) {\\r\\n    addError(errors, rootDir, planPath, \\"Plan 至少需要 story.md 或 spec.md\\");\\r\\n  }\\r\\n  if (!hasSpec && lifecycle !== \\"active\\") {\\r\\n    addError(errors, rootDir, planPath, \\"非 active Plan 必须包含 spec.md\\");\\r\\n  }\\r\\n\\r\\n  for (const entry of markdownFiles) {\\r\\n    const allowed =\\r\\n      [\\"story.md\\", \\"spec.md\\"].includes(entry.name) || /^\\\\d{2}-.+\\\\.md$/.test(entry.name);\\r\\n    if (!allowed) {\\r\\n      addError(\\r\\n        errors,\\r\\n        rootDir,\\r\\n        path.join(planPath, entry.name),\\r\\n        \\"Plan 文件名必须是 story.md、spec.md 或 NN-中文标题.md\\",\\r\\n      );\\r\\n    }\\r\\n    if (![\\"story.md\\", \\"spec.md\\"].includes(entry.name) && !HAN_PATTERN.test(entry.name)) {\\r\\n      addError(errors, rootDir, path.join(planPath, entry.name), \\"Issue 文件名必须包含中文标题\\");\\r\\n    }\\r\\n    const content = readText(path.join(planPath, entry.name), errors, rootDir);\\r\\n    if (content !== null) {\\r\\n      assertChineseDocument(content, path.join(planPath, entry.name), errors, rootDir);\\r\\n    }\\r\\n  }\\r\\n  return { hasSpec, markdownFiles };\\r\\n};\\r\\n\\r\\nconst loadIssues = (planPath, markdownFiles, errors, rootDir) => {\\r\\n  const issueEntries = markdownFiles\\r\\n    .filter((entry) => /^\\\\d{2}-.+\\\\.md$/.test(entry.name))\\r\\n    .sort((left, right) => left.name.localeCompare(right.name, \\"zh-CN\\"));\\r\\n  if (issueEntries.length === 0) {\\r\\n    addError(errors, rootDir, planPath, \\"包含 spec.md 的 Plan 至少需要一个 Issue\\");\\r\\n    return [];\\r\\n  }\\r\\n\\r\\n  const issues = [];\\r\\n  for (const [index, entry] of issueEntries.entries()) {\\r\\n    const id = entry.name.slice(0, 2);\\r\\n    const expectedId = String(index + 1).padStart(2, \\"0\\");\\r\\n    if (id !== expectedId) {\\r\\n      addError(\\r\\n        errors,\\r\\n        rootDir,\\r\\n        path.join(planPath, entry.name),\\r\\n        `Issue 编号必须连续，期望 ${expectedId}`,\\r\\n      );\\r\\n    }\\r\\n    const issue = checkIssue(path.join(planPath, entry.name), id, errors, rootDir);\\r\\n    if (issue) issues.push({ ...issue, fileName: entry.name });\\r\\n  }\\r\\n  return issues;\\r\\n};\\r\\n\\r\\nconst checkIssueTable = (specContent, specPath, issues, errors, rootDir) => {\\r\\n  const issueTable = parseIssueTable(specContent);\\r\\n  for (const issue of issues) {\\r\\n    const row = issueTable.get(issue.id);\\r\\n    if (!row) {\\r\\n      addError(errors, rootDir, specPath, `Issue 表缺少 ${issue.id}`);\\r\\n      continue;\\r\\n    }\\r\\n    if (row.fileName !== issue.fileName) {\\r\\n      addError(errors, rootDir, specPath, `Issue ${issue.id} 链接应指向 ${issue.fileName}`);\\r\\n    }\\r\\n    if (row.status !== issue.status) {\\r\\n      addError(\\r\\n        errors,\\r\\n        rootDir,\\r\\n        specPath,\\r\\n        `Issue ${issue.id} 表格状态 ${row.status} 与 frontmatter ${issue.status} 不一致`,\\r\\n      );\\r\\n    }\\r\\n    if (row.dependencies.join(\\",\\") !== issue.dependencies.join(\\",\\")) {\\r\\n      addError(errors, rootDir, specPath, `Issue ${issue.id} 表格依赖与 blocked_by 不一致`);\\r\\n    }\\r\\n  }\\r\\n  for (const id of issueTable.keys()) {\\r\\n    if (!issues.some((issue) => issue.id === id)) {\\r\\n      addError(errors, rootDir, specPath, `Issue 表引用了不存在的 ${id}`);\\r\\n    }\\r\\n  }\\r\\n};\\r\\n\\r\\nconst checkSpec = (planPath, lifecycle, markdownFiles, errors, rootDir) => {\\r\\n  const specPath = path.join(planPath, \\"spec.md\\");\\r\\n  const specContent = readText(specPath, errors, rootDir);\\r\\n  if (specContent === null) return;\\r\\n  const specFrontmatter = parseFrontmatter(specContent, specPath, errors, rootDir);\\r\\n  for (const heading of [\\r\\n    \\"问题\\",\\r\\n    \\"方案\\",\\r\\n    \\"已排除的备选\\",\\r\\n    \\"实施决策\\",\\r\\n    \\"工作环境\\",\\r\\n    \\"范围\\",\\r\\n    \\"非范围\\",\\r\\n    \\"待定\\",\\r\\n    \\"上下文\\",\\r\\n    \\"Issue\\",\\r\\n  ]) {\\r\\n    if (!hasSection(specContent, heading)) {\\r\\n      addError(errors, rootDir, specPath, `缺少「## ${heading}」章节`);\\r\\n    }\\r\\n  }\\r\\n  const specStatus = specFrontmatter.get(\\"status\\");\\r\\n  if (!SPEC_STATUSES.has(specStatus)) {\\r\\n    addError(errors, rootDir, specPath, `status 必须是 ${[...SPEC_STATUSES].join(\\" | \\")}`);\\r\\n  }\\r\\n  const issues = loadIssues(planPath, markdownFiles, errors, rootDir);\\r\\n  if (issues.length === 0) return;\\r\\n  checkDependencyGraph(issues, planPath, errors, rootDir);\\r\\n  checkIssueTable(specContent, specPath, issues, errors, rootDir);\\r\\n  const expectedSpecStatus = deriveSpecStatus(issues);\\r\\n  if (specStatus !== expectedSpecStatus) {\\r\\n    addError(errors, rootDir, specPath, `聚合状态应为 ${expectedSpecStatus}，实际为 ${specStatus}`);\\r\\n  }\\r\\n  if (lifecycle === \\"reference\\" && expectedSpecStatus !== \\"completed\\") {\\r\\n    addError(errors, rootDir, planPath, \\"reference Plan 的 Issue 必须全部 completed\\");\\r\\n  }\\r\\n};\\r\\n\\r\\nconst checkPlan = (planPath, lifecycle, errors, rootDir) => {\\r\\n  const layout = checkPlanLayout(planPath, lifecycle, errors, rootDir);\\r\\n  if (layout.hasSpec) {\\r\\n    checkSpec(planPath, lifecycle, layout.markdownFiles, errors, rootDir);\\r\\n  }\\r\\n};\\r\\n\\r\\nconst checkPlans = (domainPath, errors, rootDir) => {\\r\\n  const plansPath = path.join(domainPath, \\"plans\\");\\r\\n  if (!fs.existsSync(plansPath)) return;\\r\\n  const lifecycleEntries = readEntries(plansPath, errors, rootDir).filter((entry) =>\\r\\n    entry.isDirectory(),\\r\\n  );\\r\\n  for (const lifecycleEntry of lifecycleEntries) {\\r\\n    if (!LIFECYCLES.has(lifecycleEntry.name)) {\\r\\n      addError(\\r\\n        errors,\\r\\n        rootDir,\\r\\n        path.join(plansPath, lifecycleEntry.name),\\r\\n        \\"Plan 生命周期目录只能是 active、reference 或 archived\\",\\r\\n      );\\r\\n      continue;\\r\\n    }\\r\\n    const lifecyclePath = path.join(plansPath, lifecycleEntry.name);\\r\\n    for (const planEntry of readEntries(lifecyclePath, errors, rootDir).filter((entry) =>\\r\\n      entry.isDirectory(),\\r\\n    )) {\\r\\n      checkPlan(path.join(lifecyclePath, planEntry.name), lifecycleEntry.name, errors, rootDir);\\r\\n    }\\r\\n  }\\r\\n};\\r\\n\\r\\nconst checkAdrs = (domainPath, errors, rootDir) => {\\r\\n  const adrPath = path.join(domainPath, \\"adr\\");\\r\\n  if (!fs.existsSync(adrPath)) return;\\r\\n  const adrFiles = readEntries(adrPath, errors, rootDir)\\r\\n    .filter((entry) => entry.isFile() && entry.name.endsWith(\\".md\\"))\\r\\n    .sort((left, right) => left.name.localeCompare(right.name, \\"zh-CN\\"));\\r\\n  if (adrFiles.length > 89) {\\r\\n    addError(errors, rootDir, adrPath, `ADR 数量 ${adrFiles.length} 超过 89`);\\r\\n  }\\r\\n  for (const [index, adrFile] of adrFiles.entries()) {\\r\\n    const adrFilePath = path.join(adrPath, adrFile.name);\\r\\n    const nameMatch = adrFile.name.match(/^(\\\\d{4})-(.+)\\\\.md$/);\\r\\n    const expectedId = String(index + 1).padStart(4, \\"0\\");\\r\\n    if (!nameMatch || nameMatch[1] !== expectedId || !HAN_PATTERN.test(nameMatch[2])) {\\r\\n      addError(\\r\\n        errors,\\r\\n        rootDir,\\r\\n        adrFilePath,\\r\\n        `ADR 文件名必须按域内连续编号，期望 ${expectedId}-中文决策名.md`,\\r\\n      );\\r\\n    }\\r\\n    const content = readText(adrFilePath, errors, rootDir);\\r\\n    if (content === null) continue;\\r\\n    assertChineseDocument(content, adrFilePath, errors, rootDir);\\r\\n    const lineCount = countLines(content);\\r\\n    if (lineCount > 144) {\\r\\n      addError(errors, rootDir, adrFilePath, `ADR 共 ${lineCount} 行，超过 144`);\\r\\n    }\\r\\n  }\\r\\n};\\r\\n\\r\\nexport const checkDomain = (rootDirectory) => {\\r\\n  const rootDir = path.resolve(rootDirectory);\\r\\n  const errors = [];\\r\\n  const policyPath = path.resolve(\\r\\n    path.dirname(fileURLToPath(import.meta.url)),\\r\\n    \\"..\\",\\r\\n    \\"references\\",\\r\\n    \\"DOMAIN.md\\",\\r\\n  );\\r\\n  if (!fs.existsSync(policyPath)) {\\r\\n    addError(errors, rootDir, policyPath, \\"/nano-flow 缺少 references/DOMAIN.md\\");\\r\\n  }\\r\\n  for (const requiredFile of [\\"CONTEXT-MAP.md\\"]) {\\r\\n    if (!fs.existsSync(path.join(rootDir, requiredFile))) {\\r\\n      addError(errors, rootDir, path.join(rootDir, requiredFile), \\"文件不存在\\");\\r\\n    }\\r\\n  }\\r\\n  const docsPath = path.join(rootDir, \\"docs\\");\\r\\n  if (!fs.existsSync(docsPath)) {\\r\\n    addError(errors, rootDir, docsPath, \\"目录不存在\\");\\r\\n    return errors;\\r\\n  }\\r\\n  const mapPath = path.join(rootDir, \\"CONTEXT-MAP.md\\");\\r\\n  const mapContent = fs.existsSync(mapPath) ? readText(mapPath, errors, rootDir) : null;\\r\\n  const domainEntries = readEntries(docsPath, errors, rootDir).filter((entry) =>\\r\\n    entry.isDirectory(),\\r\\n  );\\r\\n  const domainNames = new Set(domainEntries.map((entry) => entry.name));\\r\\n\\r\\n  for (const domainEntry of domainEntries) {\\r\\n    const domainPath = path.join(docsPath, domainEntry.name);\\r\\n    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(domainEntry.name)) {\\r\\n      addError(errors, rootDir, domainPath, \\"domain-name 必须是 kebab-case\\");\\r\\n    }\\r\\n    const contextPath = path.join(domainPath, \\"CONTEXT.md\\");\\r\\n    if (!fs.existsSync(contextPath)) {\\r\\n      addError(errors, rootDir, contextPath, \\"业务域缺少 CONTEXT.md\\");\\r\\n    } else {\\r\\n      const content = readText(contextPath, errors, rootDir);\\r\\n      if (content !== null) {\\r\\n        assertChineseDocument(content, contextPath, errors, rootDir);\\r\\n        const lineCount = countLines(content);\\r\\n        if (lineCount > 610) {\\r\\n          addError(errors, rootDir, contextPath, `CONTEXT.md 共 ${lineCount} 行，超过 610`);\\r\\n        }\\r\\n      }\\r\\n    }\\r\\n    if (mapContent !== null && !mapContent.includes(`(./docs/${domainEntry.name}/CONTEXT.md)`)) {\\r\\n      addError(errors, rootDir, mapPath, `缺少业务域 ${domainEntry.name} 的索引`);\\r\\n    }\\r\\n    checkAdrs(domainPath, errors, rootDir);\\r\\n    checkPlans(domainPath, errors, rootDir);\\r\\n  }\\r\\n\\r\\n  if (mapContent !== null) {\\r\\n    for (const match of mapContent.matchAll(/\\\\(\\\\.\\\\/docs\\\\/([^/]+)\\\\/CONTEXT\\\\.md\\\\)/g)) {\\r\\n      if (!domainNames.has(match[1])) {\\r\\n        addError(errors, rootDir, mapPath, `索引指向不存在的业务域 ${match[1]}`);\\r\\n      }\\r\\n    }\\r\\n  }\\r\\n\\r\\n  return errors;\\r\\n};\\r\\n\\r\\nexport const runDomainCheck = ({\\r\\n  rootDirectory = process.argv[2] ?? process.cwd(),\\r\\n  stderr = (message) => console.error(message),\\r\\n  stdout = (message) => console.log(message),\\r\\n} = {}) => {\\r\\n  const rootDir = path.resolve(rootDirectory);\\r\\n  try {\\r\\n    const errors = checkDomain(rootDir);\\r\\n    if (errors.length > 0) {\\r\\n      stderr(`领域文档校验失败，共 ${errors.length} 项：`);\\r\\n      for (const error of errors) stderr(`- ${error}`);\\r\\n      return 1;\\r\\n    }\\r\\n    stdout(\\"领域文档校验通过。\\");\\r\\n    return 0;\\r\\n  } catch (error) {\\r\\n    stderr(`领域文档校验异常: ${error instanceof Error ? error.stack : String(error)}`);\\r\\n    return 1;\\r\\n  }\\r\\n};\\r\\n\\r\\nconst invokedPath = process.argv[1] ? path.resolve(process.argv[1]) : \\"\\";\\r\\nif (invokedPath === fileURLToPath(import.meta.url)) process.exitCode = runDomainCheck();\\r\\n"},{"path":"scripts/flow-documents.mjs","content":"import fs from \\"node:fs/promises\\";\\nimport path from \\"node:path\\";\\nimport {\\n  deriveSpecStatus,\\n  ISSUE_STATUSES,\\n  parseFrontmatter,\\n  parseIssueDependencies,\\n} from \\"./plan-document.mjs\\";\\nimport { fail } from \\"./flow-store.mjs\\";\\n\\nconst fields = (content, file) => {\\n  const parsed = typeof content === \\"string\\" && parseFrontmatter(content);\\n  if (!parsed) fail(`${file} 缺少 YAML frontmatter`);\\n  return parsed;\\n};\\n\\nconst replaceStatus = (content, status, file) => {\\n  const parsed = fields(content, file);\\n  if (!parsed.fields.has(\\"status\\")) fail(`${file} 缺少 status`);\\n  return content.replace(\\n    parsed.match[0],\\n    parsed.match[0].replace(/^status:.*$/m, `status: ${status}`),\\n  );\\n};\\n\\nexport const loadDocuments = async (store, workspace, plan) => {\\n  const specPath = `${plan}/spec.md`;\\n  const spec = await store.read(specPath);\\n  fields(spec, specPath);\\n  const entries = await fs.readdir(path.resolve(workspace, plan), { withFileTypes: true });\\n  const issues = [];\\n  for (const entry of entries\\n    .filter((item) => item.isFile() && /^\\\\d{2}-.+\\\\.md$/.test(item.name))\\n    .sort((a, b) => a.name.localeCompare(b.name))) {\\n    const file = `${plan}/${entry.name}`;\\n    const content = await store.read(file);\\n    const frontmatter = fields(content, file).fields;\\n    const status = frontmatter.get(\\"status\\");\\n    if (!ISSUE_STATUSES.includes(status)) fail(`${file} 的 status 无效`);\\n    const parsed = parseIssueDependencies(frontmatter.get(\\"blocked_by\\"));\\n    if (parsed.kind !== \\"valid\\") fail(`${file} 的 blocked_by 必须是两位 Issue ID 的 JSON 数组`);\\n    const id = entry.name.slice(0, 2);\\n    if (issues.some((issue) => issue.id === id)) fail(`重复 Issue ${id}`);\\n    issues.push({ id, path: file, content, status, dependencies: parsed.dependencies });\\n  }\\n  if (!issues.length) fail(`${plan} 没有 Issue 文件`);\\n  for (const issue of issues) {\\n    for (const dependency of issue.dependencies) {\\n      if (dependency === issue.id || !issues.some((item) => item.id === dependency))\\n        fail(`Issue ${issue.id} 的依赖 ${dependency} 无效`);\\n    }\\n  }\\n  const visiting = new Set();\\n  const visited = new Set();\\n  const visit = (issue) => {\\n    if (visiting.has(issue.id)) fail(`Issue ${issue.id} 存在循环依赖`);\\n    if (visited.has(issue.id)) return;\\n    visiting.add(issue.id);\\n    for (const id of issue.dependencies) visit(issues.find((item) => item.id === id));\\n    visiting.delete(issue.id);\\n    visited.add(issue.id);\\n  };\\n  issues.forEach(visit);\\n  return { issues, spec, specPath };\\n};\\n\\nexport const issueReady = (documents, issue) =>\\n  issue.dependencies.every(\\n    (id) => documents.issues.find((item) => item.id === id).status === \\"completed\\",\\n  );\\n\\nexport const setIssueStatus = (issue, status) => {\\n  issue.content = replaceStatus(issue.content, status, issue.path);\\n  issue.status = status;\\n};\\n\\nexport const blockIssue = (issue, reason, condition) => {\\n  const section = `## 阻塞记录\\\\n\\\\n- 障碍: ${reason}\\\\n- 解除条件: ${condition}\\\\n\\\\n`;\\n  const pattern = /^## 阻塞记录\\\\r?\\\\n[\\\\s\\\\S]*?(?=^## |(?![\\\\s\\\\S]))/m;\\n  issue.content = pattern.test(issue.content)\\n    ? issue.content.replace(pattern, section)\\n    : `${issue.content.trimEnd()}\\\\n\\\\n${section}`;\\n  setIssueStatus(issue, \\"blocked\\");\\n};\\n\\nexport const hasDeliveryEvidence = (content) => {\\n  const section = content.match(/^## (?:交付记录|交付物与证据)\\\\r?\\\\n([\\\\s\\\\S]*?)(?=^## |(?![\\\\s\\\\S]))/m);\\n  if (!section) return false;\\n  const body = section[1]\\n    .split(/\\\\r?\\\\n/)\\n    .filter((line) => !/^\\\\s*\\\\{.*\\\\}\\\\s*$/.test(line))\\n    .join(\\"\\\\n\\");\\n  return body.includes(\\"交付物\\") && body.includes(\\"证据\\");\\n};\\n\\nexport const stageDocuments = async (store, documents) => {\\n  let spec = replaceStatus(documents.spec, deriveSpecStatus(documents.issues), documents.specPath);\\n  for (const issue of documents.issues) {\\n    const row = new RegExp(\\n      `^(\\\\\\\\|\\\\\\\\s*${issue.id}\\\\\\\\s*\\\\\\\\|\\\\\\\\s*\\\\\\\\[[^\\\\\\\\]]+\\\\\\\\]\\\\\\\\([^)]+\\\\\\\\)\\\\\\\\s*\\\\\\\\|\\\\\\\\s*)(pending|in_progress|blocked|completed)(\\\\\\\\s*\\\\\\\\|.*)$`,\\n      \\"m\\",\\n    );\\n    if (!row.test(spec)) fail(`${documents.specPath} 的 Issue 表缺少 ${issue.id}`);\\n    spec = spec.replace(row, `$1${issue.status}$3`);\\n    await store.stage(issue.path, issue.content);\\n  }\\n  await store.stage(documents.specPath, spec);\\n};\\n"},{"path":"scripts/flow-store.mjs","content":"import fs from \\"node:fs/promises\\";\\nimport path from \\"node:path\\";\\nimport process from \\"node:process\\";\\nimport { randomUUID } from \\"node:crypto\\";\\n\\nexport const fail = (message) => {\\n  throw new Error(message);\\n};\\n\\nexport const planKey = (workspace, input) => {\\n  const relative = path.relative(workspace, path.resolve(workspace, input)).replaceAll(\\"\\\\\\\\\\", \\"/\\");\\n  if (relative === \\"..\\" || relative.startsWith(\\"../\\") || path.isAbsolute(relative)) {\\n    fail(\\"--plan 必须位于工作区内\\");\\n  }\\n  return relative || \\".\\";\\n};\\n\\nexport const canonicalPlanKey = async (workspace, input) => {\\n  let existing = path.resolve(workspace, input);\\n  const missing = [];\\n  for (;;) {\\n    try {\\n      const real = await fs.realpath(existing);\\n      const key = planKey(workspace, path.join(real, ...missing));\\n      return process.platform === \\"win32\\" ? key.toLowerCase() : key;\\n    } catch (error) {\\n      if (error.code !== \\"ENOENT\\") throw error;\\n      missing.unshift(path.basename(existing));\\n      existing = path.dirname(existing);\\n    }\\n  }\\n};\\n\\nconst readText = async (file) => {\\n  try {\\n    return await fs.readFile(file, \\"utf8\\");\\n  } catch (error) {\\n    if (error.code === \\"ENOENT\\") return null;\\n    throw error;\\n  }\\n};\\n\\nconst safePath = async (workspace, relative) => {\\n  const file = path.resolve(workspace, relative);\\n  planKey(workspace, file);\\n  let existing = file;\\n  for (;;) {\\n    try {\\n      planKey(workspace, await fs.realpath(existing));\\n      return file;\\n    } catch (error) {\\n      if (error.code !== \\"ENOENT\\") throw error;\\n      existing = path.dirname(existing);\\n    }\\n  }\\n};\\n\\nconst atomicWrite = async (file, content) => {\\n  const temporary = `${file}.${randomUUID()}.tmp`;\\n  let handle;\\n  try {\\n    handle = await fs.open(temporary, \\"wx\\");\\n    await handle.writeFile(content, \\"utf8\\");\\n    await handle.sync();\\n    await handle.close();\\n    handle = null;\\n    await fs.rename(temporary, file);\\n  } finally {\\n    if (handle) await handle.close();\\n    await fs.unlink(temporary).catch((error) => {\\n      if (error.code !== \\"ENOENT\\") throw error;\\n    });\\n  }\\n};\\n\\nconst parseJson = (content, name) => {\\n  try {\\n    return JSON.parse(content);\\n  } catch {\\n    fail(`${name} 不是有效 JSON`);\\n  }\\n};\\n\\nconst removeOwnFile = async (file) => {\\n  await fs.unlink(file).catch((error) => {\\n    if (error.code !== \\"ENOENT\\") throw error;\\n  });\\n};\\n\\nconst contenders = async (directory) => {\\n  const result = [];\\n  for (const name of await fs.readdir(directory)) {\\n    const match = name.match(/^(\\\\d+)-[0-9a-f-]+\\\\.lock$/);\\n    if (!match) continue;\\n    const file = path.join(directory, name);\\n    try {\\n      process.kill(Number(match[1]), 0);\\n    } catch (error) {\\n      if (error.code === \\"ESRCH\\") {\\n        await removeOwnFile(file);\\n        continue;\\n      }\\n      if (error.code !== \\"EPERM\\") throw error;\\n    }\\n    const content = await readText(file);\\n    if (content === null) continue;\\n    const ticket = Number(content);\\n    if (!Number.isSafeInteger(ticket) || ticket < 0) fail(\\"Flow 写锁记录无效\\");\\n    result.push({ name, ticket });\\n  }\\n  return result;\\n};\\n\\n// Bakery 排队：每次调用只拥有自己的唯一文件，回收死进程不会误删新持有者的锁。\\nconst lock = async (directory) => {\\n  await fs.mkdir(directory, { recursive: true });\\n  const name = `${process.pid}-${randomUUID()}.lock`;\\n  const file = path.join(directory, name);\\n  try {\\n    await fs.writeFile(file, \\"0\\", { flag: \\"wx\\" });\\n    const ticket = Math.max(0, ...(await contenders(directory)).map((item) => item.ticket)) + 1;\\n    if (!Number.isSafeInteger(ticket)) fail(\\"Flow 写锁序号超出范围\\");\\n    await atomicWrite(file, String(ticket));\\n    for (let attempt = 0; attempt < 50; attempt += 1) {\\n      const waiting = (await contenders(directory)).some(\\n        (item) =>\\n          item.name !== name &&\\n          (item.ticket === 0 ||\\n            item.ticket < ticket ||\\n            (item.ticket === ticket && item.name < name)),\\n      );\\n      if (!waiting) return () => removeOwnFile(file);\\n      await new Promise((resolve) => setTimeout(resolve, 100));\\n    }\\n    fail(\\"等待 Flow 写锁超时\\");\\n  } catch (error) {\\n    await removeOwnFile(file);\\n    throw error;\\n  }\\n};\\n\\nconst recover = async (workspace, journalFile, readonly) => {\\n  const raw = await readText(journalFile);\\n  if (raw === null) return;\\n  if (readonly) fail(\\"存在未完成写入，请先 acquire 恢复\\");\\n  const journal = parseJson(raw, \\"Flow 写入记录\\");\\n  if (!Array.isArray(journal) || journal.length === 0) fail(\\"Flow 写入记录无效\\");\\n  const pending = [];\\n  for (const entry of journal) {\\n    if (\\n      !entry ||\\n      typeof entry.path !== \\"string\\" ||\\n      typeof entry.after !== \\"string\\" ||\\n      (entry.before !== null && typeof entry.before !== \\"string\\")\\n    )\\n      fail(\\"Flow 写入记录无效\\");\\n    const file = await safePath(workspace, entry.path);\\n    if (\\n      file === journalFile ||\\n      planKey(workspace, file).startsWith(\\".flow/locks\\") ||\\n      planKey(workspace, file) === \\".flow/state.lock\\"\\n    )\\n      fail(\\"Flow 写入目标无效\\");\\n    const current = await readText(file);\\n    if (current !== entry.before && current !== entry.after) {\\n      fail(`恢复冲突: ${entry.path} 已被外部修改；保留 pending.json 并先核对文件`);\\n    }\\n    if (current !== entry.after) pending.push({ file, before: entry.before, content: entry.after });\\n  }\\n  for (const entry of pending) {\\n    // 外部编辑不参与 Flow 锁；每次替换前重新检查，缩短检查与写入之间的窗口。\\n    const current = await readText(entry.file);\\n    if (current === entry.content) continue;\\n    if (current !== entry.before) fail(`恢复冲突: ${entry.file} 已被外部修改`);\\n    await atomicWrite(entry.file, entry.content);\\n  }\\n  await fs.unlink(journalFile);\\n};\\n\\n// 先计算全部最终内容，再持久化写入意图；中断后只补写未完成且未被外部编辑的文件。\\nexport const withFlowStore = async (workspace, readonly, action) => {\\n  const directory = await safePath(workspace, \\".flow\\");\\n  await fs.mkdir(directory, { recursive: true });\\n  const lockDirectory = await safePath(workspace, \\".flow/locks\\");\\n  const journalFile = await safePath(workspace, \\".flow/pending.json\\");\\n  const unlock = await lock(lockDirectory);\\n  try {\\n    await recover(workspace, journalFile, readonly);\\n    const snapshots = new Map();\\n    const writes = new Map();\\n    const read = async (relative) => {\\n      if (!snapshots.has(relative))\\n        snapshots.set(relative, await readText(await safePath(workspace, relative)));\\n      return snapshots.get(relative);\\n    };\\n    const stage = async (relative, after) => {\\n      const before = await read(relative);\\n      if (before !== after) writes.set(relative, { path: relative, before, after });\\n    };\\n    const stateText = await read(\\".flow/state.json\\");\\n    const state =\\n      stateText === null ? { schema_version: 7, plans: {} } : parseJson(stateText, \\"Flow 状态\\");\\n    const output = await action({ state, read, stage });\\n    if (!readonly) {\\n      await stage(\\".flow/state.json\\", `${JSON.stringify(state, null, 2)}\\\\n`);\\n      if (writes.size) {\\n        await atomicWrite(journalFile, `${JSON.stringify([...writes.values()])}\\\\n`);\\n        await recover(workspace, journalFile, false);\\n      }\\n    }\\n    return output;\\n  } finally {\\n    await unlock();\\n  }\\n};\\n"},{"path":"scripts/flow.mjs","content":"#!/usr/bin/env node\\n\\nimport fs from \\"node:fs/promises\\";\\nimport path from \\"node:path\\";\\nimport process from \\"node:process\\";\\nimport { randomUUID } from \\"node:crypto\\";\\nimport { fileURLToPath } from \\"node:url\\";\\nimport { canonicalPlanKey, fail, planKey, withFlowStore } from \\"./flow-store.mjs\\";\\nimport {\\n  loadDocuments,\\n  issueReady,\\n  setIssueStatus,\\n  blockIssue,\\n  hasDeliveryEvidence,\\n  stageDocuments,\\n} from \\"./flow-documents.mjs\\";\\n\\nconst SKILLS = [\\"questing\\", \\"to-issues\\", \\"code-delivery\\"];\\nconst HOOK_SCHEMA_VERSION = 1;\\nconst HOOKS_PATH = fileURLToPath(new URL(\\"../extensions/hooks.json\\", import.meta.url));\\nconst HOOKABLE_SKILLS = new Set(SKILLS);\\nconst FLOW_MODES = new Set([\\"auto\\", \\"manual\\"]);\\nconst DEFAULT_FLOW_MODE = \\"manual\\";\\nconst normalizeSkill = (value) => value?.replace(/^\\\\//, \\"\\");\\n\\nconst validateHooks = (config) => {\\n  if (\\n    config === null ||\\n    config.schema_version !== HOOK_SCHEMA_VERSION ||\\n    !Array.isArray(config.hooks)\\n  ) {\\n    fail(\\"Hook 配置格式无效或版本不受支持\\");\\n  }\\n  for (const [index, hook] of config.hooks.entries()) {\\n    if (hook === null || typeof hook !== \\"object\\" || Array.isArray(hook)) {\\n      fail(`Hook ${index + 1} 格式无效`);\\n    }\\n    if (\\n      hook.match !== \\"all\\" &&\\n      (!Array.isArray(hook.match) ||\\n        hook.match.length === 0 ||\\n        hook.match.some((skill) => typeof skill !== \\"string\\" || !HOOKABLE_SKILLS.has(skill)))\\n    ) {\\n      fail(`Hook ${index + 1} 的 match 必须是 \\"all\\" 或主流程 Skill 数组`);\\n    }\\n    if (hook.mode !== undefined && hook.mode !== \\"all\\" && !FLOW_MODES.has(hook.mode)) {\\n      fail(`Hook ${index + 1} 的 mode 必须是 all | manual | auto`);\\n    }\\n    if (\\n      typeof hook.message !== \\"string\\" ||\\n      hook.message.trim() === \\"\\" ||\\n      /[\\\\r\\\\n]/u.test(hook.message)\\n    ) {\\n      fail(`Hook ${index + 1} 的 message 必须是非空单行字符串`);\\n    }\\n  }\\n  return config;\\n};\\n\\nconst loadHooks = async (hooksPath = HOOKS_PATH) => {\\n  let content;\\n  try {\\n    content = await fs.readFile(hooksPath, \\"utf8\\");\\n  } catch (error) {\\n    fail(\\n      `读取 Hook 配置 ${hooksPath} 失败: ${error instanceof Error ? error.message : String(error)}`,\\n    );\\n  }\\n  try {\\n    return validateHooks(JSON.parse(content));\\n  } catch (error) {\\n    if (error instanceof SyntaxError) fail(`解析 Hook 配置 ${hooksPath} 失败: ${error.message}`);\\n    throw error;\\n  }\\n};\\n\\nconst messageForSkill = (config, skill, mode) => {\\n  const normalized = normalizeSkill(skill);\\n  return config.hooks\\n    .filter((hook) => hook.match === \\"all\\" || hook.match.includes(normalized))\\n    .filter((hook) => hook.mode === undefined || hook.mode === \\"all\\" || hook.mode === mode)\\n    .map((hook) => hook.message)\\n    .join(\\"\\\\n\\");\\n};\\n\\nconst requireOption = (options, name) => {\\n  const value = options[name];\\n  if (typeof value !== \\"string\\" || value.trim() === \\"\\") fail(`缺少 --${name}`);\\n  return value.trim();\\n};\\n\\nconst evidenceOf = (options) => {\\n  const items =\\n    options.evidence === undefined\\n      ? []\\n      : Array.isArray(options.evidence)\\n        ? options.evidence\\n        : [options.evidence];\\n  if (items.some((item) => typeof item !== \\"string\\" || !item.trim()))\\n    fail(\\"--evidence 必须是非空引用\\");\\n  return items.map((item) => item.trim());\\n};\\n\\nconst parseOptions = (command, options, workspace) => {\\n  const allowed = {\\n    status: [\\"plan\\", \\"issue\\", \\"session\\"],\\n    acquire: [\\"plan\\", \\"issue\\", \\"session\\", \\"mode\\", \\"lease-seconds\\", \\"evidence\\"],\\n    report: [\\n      \\"plan\\",\\n      \\"issue\\",\\n      \\"session\\",\\n      \\"step\\",\\n      \\"result\\",\\n      \\"evidence\\",\\n      \\"reason\\",\\n      \\"release-condition\\",\\n      \\"lease-seconds\\",\\n    ],\\n  };\\n  if (!Object.hasOwn(allowed, command)) fail(`未知命令 ${command}`);\\n  for (const key of Object.keys(options)) {\\n    if (!allowed[command].includes(key)) fail(`无法识别参数 --${key}`);\\n    if (key !== \\"evidence\\") requireOption(options, key);\\n  }\\n  const plan = planKey(workspace, requireOption(options, \\"plan\\"));\\n  const issue = options.issue?.trim() ?? null;\\n  if (issue !== null && !/^\\\\d{2}$/.test(issue)) fail(\\"--issue 必须是两位 Issue ID\\");\\n  const mode = options.mode?.trim();\\n  if (mode !== undefined && !FLOW_MODES.has(mode)) fail(\\"--mode 必须是 manual | auto\\");\\n  const seconds = options[\\"lease-seconds\\"] === undefined ? 1800 : Number(options[\\"lease-seconds\\"]);\\n  if (!Number.isInteger(seconds) || seconds < 30 || seconds > 86400)\\n    fail(\\"--lease-seconds 必须是 30 到 86400 之间的整数\\");\\n  const input = {\\n    plan,\\n    issue,\\n    mode,\\n    seconds,\\n    session: options.session?.trim() ?? null,\\n    evidence: evidenceOf(options),\\n  };\\n  if (command !== \\"report\\") return input;\\n  input.session = requireOption(options, \\"session\\");\\n  input.result = requireOption(options, \\"result\\");\\n  if (![\\"completed\\", \\"skipped\\", \\"paused\\", \\"blocked\\"].includes(input.result))\\n    fail(\\"--result 必须是 completed | skipped | paused | blocked\\");\\n  if (input.result === \\"blocked\\") {\\n    if (!issue) fail(\\"blocked 仅适用于 Issue\\");\\n    input.reason = requireOption(options, \\"reason\\");\\n    input.condition = requireOption(options, \\"release-condition\\");\\n  } else if (input.result !== \\"paused\\") {\\n    input.step = `/${normalizeSkill(requireOption(options, \\"step\\"))}`;\\n    if (!input.evidence.length) fail(`${input.step} 至少需要一个 --evidence`);\\n  }\\n  return input;\\n};\\n\\nconst isObject = (value) => value !== null && typeof value === \\"object\\" && !Array.isArray(value);\\nconst leaseActive = (lease, now) => lease && Date.parse(lease.expires_at) > now.getTime();\\nconst makeLease = (input, now) => ({\\n  owner_session: input.session,\\n  expires_at: new Date(now.getTime() + input.seconds * 1000).toISOString(),\\n});\\nconst planReceipts = (plan) => plan.receipts.filter((receipt) => receipt.issue === null);\\nconst planStep = (plan) => {\\n  const receipts = planReceipts(plan);\\n  if (!receipts.length) return \\"questing\\";\\n  if (receipts.length === 1) return \\"to-issues\\";\\n  if (receipts[1].result === \\"completed\\") return \\"issues\\";\\n  return receipts.length === 2 ? \\"code-delivery\\" : \\"completed\\";\\n};\\n\\nconst validatePlan = (plan) => {\\n  if (\\n    !isObject(plan) ||\\n    !FLOW_MODES.has(plan.mode) ||\\n    !Array.isArray(plan.receipts) ||\\n    !isObject(plan.leases)\\n  )\\n    fail(\\"Flow Plan 状态格式无效\\");\\n  const seen = { mode: plan.mode, receipts: [] };\\n  const completedIssues = new Set();\\n  for (const receipt of plan.receipts) {\\n    if (\\n      !isObject(receipt) ||\\n      (receipt.issue !== null &&\\n        (typeof receipt.issue !== \\"string\\" || !/^\\\\d{2}$/.test(receipt.issue))) ||\\n      !Array.isArray(receipt.evidence) ||\\n      !receipt.evidence.length ||\\n      receipt.evidence.some((item) => typeof item !== \\"string\\" || !item.trim()) ||\\n      typeof receipt.recorded_at !== \\"string\\" ||\\n      !Number.isFinite(Date.parse(receipt.recorded_at))\\n    )\\n      fail(\\"Flow receipt 格式无效\\");\\n    const expected = planStep(seen);\\n    if (receipt.issue === null) {\\n      if (\\n        receipt.step !== `/${expected}` ||\\n        !SKILLS.includes(expected) ||\\n        !(\\n          receipt.result === \\"completed\\" ||\\n          (expected === \\"to-issues\\" && receipt.result === \\"skipped\\")\\n        )\\n      )\\n        fail(\\"Flow receipt 顺序或结果无效\\");\\n    } else {\\n      if (\\n        expected !== \\"issues\\" ||\\n        completedIssues.has(receipt.issue) ||\\n        receipt.step !== \\"/code-delivery\\" ||\\n        receipt.result !== \\"completed\\"\\n      )\\n        fail(\\"Flow Issue receipt 顺序或结果无效\\");\\n      completedIssues.add(receipt.issue);\\n    }\\n    seen.receipts.push(receipt);\\n  }\\n  for (const [target, lease] of Object.entries(plan.leases)) {\\n    if (\\n      (target !== \\"plan\\" && !/^\\\\d{2}$/.test(target)) ||\\n      !isObject(lease) ||\\n      typeof lease.owner_session !== \\"string\\" ||\\n      !lease.owner_session.trim() ||\\n      typeof lease.expires_at !== \\"string\\" ||\\n      !Number.isFinite(Date.parse(lease.expires_at))\\n    )\\n      fail(\\"Flow 租约格式无效\\");\\n    if (\\n      (target === \\"plan\\" && [\\"issues\\", \\"completed\\"].includes(planStep(plan))) ||\\n      (target !== \\"plan\\" && (planStep(plan) !== \\"issues\\" || completedIssues.has(target)))\\n    )\\n      fail(\\"Flow 租约与步骤冲突\\");\\n  }\\n};\\n\\nconst validateState = (state, workspace) => {\\n  if (!isObject(state) || state.schema_version !== 7 || !isObject(state.plans))\\n    fail(\\"Flow 状态格式无效或版本不受支持；需要 schema_version=7\\");\\n  for (const [key, plan] of Object.entries(state.plans)) {\\n    if (key !== planKey(workspace, key)) fail(\\"Flow 标识无效\\");\\n    validatePlan(plan);\\n  }\\n};\\n\\nconst findIssue = (documents, id) => {\\n  const issue = documents?.issues.find((item) => item.id === id);\\n  if (!issue) fail(`Plan 中不存在 Issue ${id}`);\\n  return issue;\\n};\\n\\nconst requireLease = (lease, session, now) => {\\n  if (!leaseActive(lease, now)) fail(\\"租约不存在或已经过期，请 acquire 恢复\\");\\n  if (lease.owner_session !== session) fail(`资源由会话 ${lease.owner_session} 持有`);\\n};\\n\\nconst project = (plan, documents, input, now, hooks) => {\\n  const issue = input.issue ? findIssue(documents, input.issue) : null;\\n  const step = issue\\n    ? issue.status === \\"completed\\"\\n      ? \\"completed\\"\\n      : \\"code-delivery\\"\\n    : planStep(plan);\\n  const done =\\n    step === \\"completed\\" ||\\n    (step === \\"issues\\" && documents.issues.every((item) => item.status === \\"completed\\"));\\n  const lease = done ? null : (plan.leases[input.issue ?? \\"plan\\"] ?? null);\\n  let state = leaseActive(lease, now)\\n    ? lease.owner_session === input.session\\n      ? \\"owned\\"\\n      : \\"busy\\"\\n    : \\"available\\";\\n  if (issue?.status === \\"blocked\\") state = \\"blocked\\";\\n  if (step === \\"issues\\") state = \\"issues\\";\\n  if (done) state = \\"completed\\";\\n  const next =\\n    !done && step !== \\"issues\\"\\n      ? {\\n          skill: `/${step}`,\\n          results: step === \\"to-issues\\" ? [\\"completed\\", \\"skipped\\"] : [\\"completed\\"],\\n        }\\n      : null;\\n  if (next) {\\n    const message = messageForSkill(hooks, next.skill, plan.mode);\\n    if (message) next.message = message;\\n  }\\n  return {\\n    plan: input.plan,\\n    issue: input.issue,\\n    session: input.session,\\n    mode: plan.mode,\\n    state,\\n    next,\\n    lease,\\n    issues: documents\\n      ? documents.issues.map((item) => ({\\n          id: item.id,\\n          status: item.status,\\n          lease: item.status === \\"completed\\" ? null : (plan.leases[item.id] ?? null),\\n          ready:\\n            [\\"pending\\", \\"in_progress\\"].includes(item.status) &&\\n            issueReady(documents, item) &&\\n            !leaseActive(plan.leases[item.id], now),\\n        }))\\n      : [],\\n    receipts: plan.receipts,\\n  };\\n};\\n\\nconst acquire = (plan, documents, input, now) => {\\n  const step = planStep(plan);\\n  if (!input.issue && [\\"issues\\", \\"completed\\"].includes(step)) return;\\n  const issue = input.issue ? findIssue(documents, input.issue) : null;\\n  if (issue?.status === \\"completed\\") return;\\n  const target = input.issue ?? \\"plan\\";\\n  const lease = plan.leases[target];\\n  if (leaseActive(lease, now) && lease.owner_session !== input.session)\\n    fail(`资源由会话 ${lease.owner_session} 持有`);\\n  input.session ??= randomUUID();\\n  if (issue) {\\n    if (!issueReady(documents, issue)) fail(`Issue ${issue.id} 的直接依赖尚未 completed`);\\n    if (\\n      Object.entries(plan.leases).some(\\n        ([id, other]) =>\\n          id !== target && leaseActive(other, now) && other.owner_session === input.session,\\n      )\\n    )\\n      fail(\\"同一 session 只能持有一个 Issue\\");\\n    if (issue.status === \\"blocked\\") {\\n      if (!input.evidence.length) fail(\\"解除 blocked 至少需要一个 --evidence\\");\\n      issue.content = `${issue.content.trimEnd()}\\\\n\\\\n- 解除证据: ${input.evidence.join(\\"；\\")}\\\\n`;\\n    }\\n    setIssueStatus(issue, \\"in_progress\\");\\n  }\\n  plan.leases[target] = makeLease(input, now);\\n};\\n\\nconst report = (plan, documents, input, now) => {\\n  const target = input.issue ?? \\"plan\\";\\n  const issue = input.issue ? findIssue(documents, input.issue) : null;\\n  if (issue && issue.status !== \\"in_progress\\")\\n    fail(`Issue ${issue.id} 当前状态 ${issue.status} 不可登记`);\\n  requireLease(plan.leases[target], input.session, now);\\n  if (input.result === \\"paused\\" || input.result === \\"blocked\\") {\\n    if (input.result === \\"blocked\\") blockIssue(issue, input.reason, input.condition);\\n    delete plan.leases[target];\\n    return;\\n  }\\n  const step = issue ? \\"code-delivery\\" : planStep(plan);\\n  if (input.step !== `/${step}`) fail(`步骤顺序错误: 期望 /${step}，实际 ${input.step}`);\\n  if (input.result === \\"skipped\\" && step !== \\"to-issues\\")\\n    fail(`${input.step} 的 result 必须是 completed`);\\n  if (issue) {\\n    if (!issueReady(documents, issue)) fail(`Issue ${issue.id} 的直接依赖尚未 completed`);\\n    if (!hasDeliveryEvidence(issue.content))\\n      fail(`Issue ${issue.id} 完成前必须写入交付物与验证证据`);\\n    setIssueStatus(issue, \\"completed\\");\\n  }\\n  plan.receipts.push({\\n    issue: input.issue,\\n    step: input.step,\\n    result: input.result,\\n    evidence: input.evidence,\\n    recorded_at: now.toISOString(),\\n  });\\n  if (issue || [\\"issues\\", \\"completed\\"].includes(planStep(plan))) delete plan.leases[target];\\n  else plan.leases[target] = makeLease(input, now);\\n};\\n\\nexport const executeFlow = async ({\\n  command,\\n  hooks,\\n  now = () => new Date(),\\n  options = {},\\n  workspace = process.cwd(),\\n}) => {\\n  const root = await fs.realpath(path.resolve(workspace));\\n  const input = parseOptions(command, options, root);\\n  input.plan = await canonicalPlanKey(root, input.plan);\\n  const config = hooks === undefined ? await loadHooks() : validateHooks(hooks);\\n  return withFlowStore(root, command === \\"status\\", async (store) => {\\n    validateState(store.state, root);\\n    let plan = Object.hasOwn(store.state.plans, input.plan) ? store.state.plans[input.plan] : null;\\n    if (!plan) {\\n      if (command !== \\"acquire\\" || input.issue) fail(`Plan ${input.plan} 尚未初始化`);\\n      plan = { mode: input.mode ?? DEFAULT_FLOW_MODE, receipts: [], leases: {} };\\n      Object.defineProperty(store.state.plans, input.plan, {\\n        value: plan,\\n        enumerable: true,\\n        configurable: true,\\n        writable: true,\\n      });\\n    }\\n    if (input.mode !== undefined && input.mode !== plan.mode)\\n      fail(\\"Flow 模式创建后固定；新模式请使用新的 Flow 标识\\");\\n    if (input.issue && planStep(plan) !== \\"issues\\") fail(\\"Plan 尚未进入 Issue 交付\\");\\n    let documents =\\n      planStep(plan) === \\"issues\\" ? await loadDocuments(store, root, input.plan) : null;\\n    if (documents) {\\n      for (const receipt of plan.receipts.filter((item) => item.issue !== null)) {\\n        if (findIssue(documents, receipt.issue).status !== \\"completed\\")\\n          fail(`Issue ${receipt.issue} 与完成 receipt 冲突；后续工作请新增 Issue`);\\n      }\\n      if (command !== \\"status\\") {\\n        for (const issue of documents.issues)\\n          if (issue.status === \\"completed\\") delete plan.leases[issue.id];\\n      }\\n    }\\n    const instant = now();\\n    if (command === \\"acquire\\") acquire(plan, documents, input, instant);\\n    if (command === \\"report\\") {\\n      report(plan, documents, input, instant);\\n      if (planStep(plan) === \\"issues\\" && !documents)\\n        documents = await loadDocuments(store, root, input.plan);\\n    }\\n    if (documents && command !== \\"status\\") await stageDocuments(store, documents);\\n    validatePlan(plan);\\n    return project(plan, documents, input, instant, config);\\n  });\\n};\\n\\nconst parseCli = (argumentsList) => {\\n  const [command = \\"help\\", ...tokens] = argumentsList;\\n  const options = Object.create(null);\\n  for (let index = 0; index < tokens.length; index += 2) {\\n    const token = tokens[index];\\n    if (!token.startsWith(\\"--\\")) fail(`无法识别参数 ${token}`);\\n    const key = token.slice(2);\\n    const value = tokens[index + 1];\\n    if (!value || value.startsWith(\\"--\\")) fail(`--${key} 缺少值`);\\n    if (key === \\"evidence\\") options.evidence = [...(options.evidence ?? []), value];\\n    else {\\n      if (Object.hasOwn(options, key)) fail(`重复参数 --${key}`);\\n      options[key] = value;\\n    }\\n  }\\n  return { command, options };\\n};\\n\\nconst usage = `用法:\\n  flow.mjs status --plan <path> [--issue <NN>] [--session <id>]\\n  flow.mjs acquire --plan <path> [--issue <NN>] [--session <id>] [--mode <manual|auto>] [--lease-seconds <30..86400>] [--evidence <解除阻塞证据>]\\n  flow.mjs report --plan <path> [--issue <NN>] --session <id> --step </questing|/to-issues|/code-delivery> --result <completed|skipped> --evidence <ref>\\n  flow.mjs report --plan <path> [--issue <NN>] --session <id> --result paused\\n  flow.mjs report --plan <path> --issue <NN> --session <id> --result blocked --reason <text> --release-condition <text>\\n\\nacquire 统一进入、恢复及续租；report completed 表示 skill 的全部工作已完成。\\n仅 /to-issues 接受 skipped。--evidence 可重复；所有命令可用 --workspace <path>。\\n`;\\n\\nexport const runFlowCli = async ({\\n  argumentsList = process.argv.slice(2),\\n  cwd = process.cwd(),\\n  stderr = (message) => console.error(message),\\n  stdout = (message) => process.stdout.write(message),\\n} = {}) => {\\n  try {\\n    const parsed = parseCli(argumentsList);\\n    if ([\\"help\\", \\"--help\\", \\"-h\\"].includes(parsed.command)) {\\n      stdout(usage);\\n      return 0;\\n    }\\n    const workspace = parsed.options.workspace ?? cwd;\\n    delete parsed.options.workspace;\\n    const result = await executeFlow({ ...parsed, workspace });\\n    stdout(`${JSON.stringify({ success: true, ...result }, null, 2)}\\\\n`);\\n    return 0;\\n  } catch (error) {\\n    stderr(JSON.stringify({ error: error.message, success: false }));\\n    return 1;\\n  }\\n};\\n\\nconst invokedPath = process.argv[1] ? path.resolve(process.argv[1]) : \\"\\";\\nif (invokedPath === fileURLToPath(import.meta.url)) process.exitCode = await runFlowCli();\\n"},{"path":"scripts/plan-document.mjs","content":"export const ISSUE_STATUSES = Object.freeze([\\"pending\\", \\"in_progress\\", \\"blocked\\", \\"completed\\"]);\\r\\n\\r\\nexport const parseFrontmatter = (content) => {\\r\\n  const match = content.match(/^---\\\\r?\\\\n([\\\\s\\\\S]*?)\\\\r?\\\\n---(?:\\\\r?\\\\n|$)/);\\r\\n  if (!match) return null;\\r\\n\\r\\n  const fields = new Map();\\r\\n  for (const line of match[1].split(/\\\\r?\\\\n/)) {\\r\\n    const field = line.match(/^([a-z_]+):(.*)/);\\r\\n    if (field) fields.set(field[1], field[2].trim());\\r\\n  }\\r\\n  return { fields, match };\\r\\n};\\r\\n\\r\\nexport const parseIssueDependencies = (rawValue) => {\\r\\n  if (rawValue === undefined) return { kind: \\"missing\\" };\\r\\n\\r\\n  let value;\\r\\n  try {\\r\\n    value = JSON.parse(rawValue);\\r\\n  } catch (error) {\\r\\n    return {\\r\\n      detail: error instanceof Error ? error.message : String(error),\\r\\n      kind: \\"invalid_json\\",\\r\\n    };\\r\\n  }\\r\\n  if (!Array.isArray(value) || value.some((dependency) => !/^\\\\d{2}$/.test(dependency))) {\\r\\n    return { kind: \\"invalid_value\\" };\\r\\n  }\\r\\n  return { dependencies: value, kind: \\"valid\\" };\\r\\n};\\r\\n\\r\\nexport const deriveSpecStatus = (issues) => {\\r\\n  if (issues.every((issue) => issue.status === \\"pending\\")) return \\"pending\\";\\r\\n  if (issues.every((issue) => issue.status === \\"completed\\")) return \\"completed\\";\\r\\n  return \\"in_progress\\";\\r\\n};\\r\\n"},{"path":"SKILL.md","content":"---\\nname: nano-flow\\ndescription: 进入、恢复或推进从故事与设计、issue 拆分到交付的 Flow，或判断下一步 skill 时使用。\\n---\\n\\n# Nano Flow\\n\\n`/nano-flow` 拥有主流程推进与 Flow context 传递；各 skill 拥有自己的步骤、产物和完成标准。\\n\\n## 选择模式\\n\\n已有 Flow 或 Plan 时，读取 [FLOW.md](./FLOW.md)，用 status 查看当前位置并 acquire 恢复。新 Flow 从 `/questing` 进入，按工作性质选择一种模式并说明理由：\\n\\n| 工作性质                       | 模式             |\\n| ------------------------------ | ---------------- |\\n| 改动大、需要用户介入与深入交互 | `manual`（默认） |\\n| 改动小、可自动推进修复或实现   | `auto`           |\\n\\n复用用户已有授权与模式偏好；只澄清会改变模式或执行范围的未决事项。模式与进入 Flow 的授权明确时完成。\\n\\n## 进入 Flow\\n\\n完整读取 [FLOW.md](./FLOW.md)，以稳定的 Plan 标识执行 acquire，传入已确定的 mode；恢复时复用 session。\\n\\n返回 owned、当前位置与目标一致且完整 context 已传给当前 skill 时完成；issues 状态先按已确认优先级领取 ready Issue。\\n\\n## 沿运行态推进\\n\\n只完整读取并执行 next.skill，原样携带同次返回的 next.message。完成条件成立后 report 真实证据，再使用新快照；交付须在提交成功后报告完成。长操作 acquire 续租，暂停或阻塞通过 report 留下可恢复状态。\\n\\n当前 skill 需要领域文档时，读取 [DOMAIN.md](references/DOMAIN.md)，以其定位、布局和生命周期为权威约束。\\n\\n目标 completed，或已登记暂停、带解除条件的 blocked 结果并释放租约时，本次路由完成。\\n"}]},{"name":"nano-flow-cli","version":"0.0.1","contentHash":"891abcb2b553aac54ccc3139c3070ae32d53a80d8551533c404e6af7562ffe1a","files":[{"path":"references/anki.md","content":"# Anki 路由\\r\\n\\r\\n`nnf anki` 经 AnkiConnect 操作桌面端 Anki。开始前确认 Anki 已启动并安装 AnkiConnect；默认地址是 `http://localhost:8765`，需要覆盖时使用 `--anki-connect <url>`。\\r\\n\\r\\n## 命令族导航\\r\\n\\r\\n| 任务                                       | 路由                                |\\r\\n| ------------------------------------------ | ----------------------------------- |\\r\\n| 牌组列表、统计、创建、移动卡片             | `nnf anki decks`                    |\\r\\n| 笔记新增、批量新增、查询、详情、更新、删除 | `nnf anki notes`                    |\\r\\n| 笔记类型、字段、样式与模板                 | `nnf anki models`                   |\\r\\n| 到期卡片、状态查询、展示与评分             | `nnf anki cards`                    |\\r\\n| 交互复习或同步 AnkiWeb                     | `nnf anki review` / `nnf anki sync` |\\r\\n| 标签增删、替换与清理                       | `nnf anki tags`                     |\\r\\n| 媒体查询、读取、写入与删除                 | `nnf anki media`                    |\\r\\n| 集合统计与复习历史                         | `nnf anki stats`                    |\\r\\n| 编辑、创建和牌组管理 GUI                   | `nnf anki gui`                      |\\r\\n\\r\\n## 工作流\\r\\n\\r\\n### 复习\\r\\n\\r\\n优先运行 `nnf anki review --deck <name> --limit <count> --include-new`。它按序同步、取卡、展示问题、从 stdin 接收 1–4 评分并汇总；输入 `q` 或 EOF 结束。需要单步控制时使用：\\r\\n\\r\\n1. `nnf anki sync`\\r\\n2. `nnf anki cards due --deck <name>`\\r\\n3. `nnf anki cards present --card-id <id>`，确认后加 `--answer`\\r\\n4. 用户确认评分后运行 `nnf anki cards rate --card-id <id> --rating <1-4>`\\r\\n\\r\\n每次评分使用本次查询所得 card ID，并由用户确认评分。会话结束后运行 `nnf anki sync` 完成收尾同步。\\r\\n\\r\\n### 建卡\\r\\n\\r\\n1. `nnf anki models fields --name <model>` 确认字段；第一字段是排序字段且必须非空。\\r\\n2. `nnf anki decks list` 确认牌组，不存在时运行 `nnf anki decks create --name <deck>`。\\r\\n3. 单张使用 `nnf anki notes add --deck <deck> --model <model> --field Front=<text> --field Back=<text>`；批量使用 `nnf anki notes add-batch --deck <deck> --model <model> --input -` 并从 stdin 提供 JSON。\\r\\n4. 需要用户在 Anki 中手动确认时使用 `nnf anki gui add-cards`，并按 leaf help 提供命名 options。\\r\\n\\r\\n新增成功后，以返回的 note ID 运行 `nnf anki notes info --note-id <id>` 复核字段。\\r\\n\\r\\n### 查询后修改\\r\\n\\r\\n先用 `nnf anki notes find --query <anki-query>` 获取 ID，再以 `nnf anki notes info --note-id <id>` 核对目标，最后用 `nnf anki notes update --id <id> --field <name=value>` 修改。每个被修改的 ID 都应来自本次会话的查询结果。\\r\\n\\r\\n## 安全与语义\\r\\n\\r\\n- 永久删除笔记、删除笔记类型字段、清理未使用标签和删除媒体前，先取得用户确认，再按 leaf help 使用 `--yes`。\\r\\n- `nnf anki notes update` 的目标正在 Anki 浏览器中打开时可能静默失败；更新前让用户关闭浏览器或切走，并在结果异常时先检查这一点。\\r\\n- `sync` 依赖桌面端已经登录 AnkiWeb。\\r\\n- `nnf anki gui` 只用于编辑、创建与牌组管理；复习使用 `nnf anki review` 或 `nnf anki cards`。\\r\\n- 统计结果中的 counts 表达今日学习队列，states 表达不受日期和上限影响的真实状态计数。\\r\\n- `nnf anki media store --file <path>` 限制媒体 MIME；URL 默认拒绝私网和环回地址；文件名会防御路径穿越。例外由 `MEDIA_ALLOWED_TYPES`、`MEDIA_IMPORT_DIR`、`MEDIA_ALLOWED_HOSTS` 控制。\\r\\n- `--read-only` 或 `READ_ONLY=true` 阻止集合写入，但保持复习评分与同步能力。\\r\\n"},{"path":"references/self.md","content":"# Self 路由\\n\\n## 命令导航\\n\\n| 任务                           | 路由                                                                         |\\n| ------------------------------ | ---------------------------------------------------------------------------- |\\n| 检查 CLI 版本                  | `nnf --version`                                                              |\\n| 更新 CLI 与已安装的受管 skills | `nnf self update`                                                            |\\n| 查看包内 skills 及安装状态     | `nnf self skill list`                                                        |\\n| 检查一个 skill                 | `nnf self skill check --name <skill>`                                        |\\n| 安装一个或全部 skills          | `nnf self skill install --name <skill>` / `nnf self skill install --all`     |\\n| 更新一个 skill                 | `nnf self skill update --name <skill>`                                       |\\n| 卸载一个或全部 skills          | `nnf self skill uninstall --name <skill>` / `nnf self skill uninstall --all` |\\n\\n`nnf self update --version <semver-or-tag>` 可选择 npm 版本或 tag；未指定时选择最新稳定版。\\n\\n## 目标目录与变更边界\\n\\n- 默认根目录为工作区 `.agents/skills`，管理其下 `nano-flow` 和 `nano-flow-cli`；`--target <root>` 指定其他根目录，不能传具体 skill 文件夹。\\n- 安装会替换同名目标，即使内容未变；先用同参数 `--dry-run` 核对 `target`。\\n- 更新与卸载遇到本地修改时保留现场并报错；只有明确要覆盖或删除这些修改时才使用 `--force`。\\n- `nnf self update` 同步 npm 包和已经安装的受管 skills；失败会回滚。可先运行 `nnf self update --dry-run` 查看 CLI 与 skill 的完整计划。\\n\\n完成标准：写操作返回成功后，用 `nnf self skill check --name <skill>` 验证状态；批量操作用 `nnf self skill list` 验证所有目标。\\n"},{"path":"SKILL.md","content":"---\\nname: nano-flow-cli\\ndescription: 使用 nnf 管理 CLI 与受管 skills，或通过 AnkiConnect 操作本机 Anki 时使用。\\n---\\n\\n# Nano Flow CLI\\n\\n按任务只读对应路由：\\n\\n- CLI 与受管 skill 管理：[self](references/self.md)。\\n- 本机 Anki 操作：[Anki](references/anki.md)。\\n\\n需求、计划与交付由 `nano-flow` 工作流路由。\\n\\n## 共享契约\\n\\n- 命令与 option 以现场 `nnf --help` 及各级 `--help` 为准，输入只用命名 option。\\n- 默认真实执行；写命令先加 `--dry-run` 核对计划，确认后移除执行。\\n- stdout 返回成功 JSON，stderr 返回错误 JSON；退出码 0=成功、1=运行时错误、2=用法错误。失败按 `hint` 修正前置。\\n"}]}]',
) as readonly ManagedSkill[];
